INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_36_all_1775004784055', 'A development team wants to ensure code quality and identify potential security vulnerabilities and performance issues early in the development cycle. They need an automated static code analysis tool that integrates directly into their AWS CodePipeline and provides actionable recommendations. Which AWS service should they integrate for the MOST effective and integrated static code analysis?', '["Amazon Inspector to scan EC2 instances for vulnerabilities after deployment.","AWS WAF to protect the application from common web exploits.","AWS Config to monitor resource compliance against security rules.","Amazon CodeGuru Reviewer integrated into an AWS CodePipeline stage."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Amazon CodeGuru Reviewer, which is specifically designed for automated static code analysis. It integrates directly into an AWS CodePipeline stage and uses machine learning to identify potential defects, security vulnerabilities, and performance issues in code, providing actionable recommendations. Option A (incorrect) Amazon Inspector is used for scanning EC2 instances and container images for vulnerabilities, typically after deployment, not for static code analysis within the pipeline. Option B (incorrect) AWS WAF is a web application firewall that protects applications from web exploits at the network edge, not a static code analysis tool. Option C (incorrect) AWS Config monitors AWS resource configurations for compliance, not the application code itself.', 36, 'm_36_2', 14, NULL, NULL),
  ('mock_36_all_1775004784055', 'A company is developing a new e-commerce platform and needs to ensure that the application can handle expected customer traffic spikes before launching to production. They want to integrate automated load testing into their CI/CD pipeline to validate performance under stress. Which approach provides the MOST effective pre-production performance validation?', '["Add a dedicated stage in AWS CodePipeline that invokes an AWS CodeBuild project to run load tests against a staging environment.","Perform manual load testing on the production environment after deployment to simulate real user traffic.","Deploy the application to production without load testing, assuming the infrastructure will scale automatically.","Run unit tests and integration tests only, as they sufficiently cover performance aspects."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective approach. Integrating a dedicated load testing stage into AWS CodePipeline, using an AWS CodeBuild project to execute load tests against a staging environment, allows for automated performance validation before production. This ensures the application can handle expected traffic and identifies bottlenecks early. Option B (incorrect) performing manual load testing on production is risky and can impact live users. Option C (incorrect) deploying to production without load testing is an anti-pattern ([ap-1.2-001]) as it risks performance issues impacting customers and assumes automatic scaling will always compensate, which is not guaranteed without validation. Option D (incorrect) unit and integration tests are crucial for functional correctness but do not adequately cover performance under load.', 36, 'm_36_2', 15, NULL, NULL),
  ('mock_36_all_1775004784055', 'A DevOps team uses AWS CodeBuild for running unit and integration tests within their CI/CD pipeline. They need a way to visualize test results, track trends over time, and quickly identify which tests are failing without manually parsing build logs. Which AWS CodeBuild feature should they utilize for the MOST efficient test result visualization and trend analysis?', '["Manually download and analyze build logs from Amazon S3 after each CodeBuild run.","Configure AWS CodeBuild to publish test reports, viewable in the CodeBuild console.","Use Amazon CloudWatch Logs Insights to query test results from raw logs.","Integrate a third-party test reporting tool that pulls data from CodeBuild."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most efficient solution. AWS CodeBuild has built-in support for publishing test reports. By configuring the `buildspec.yml` to specify test report locations, CodeBuild automatically processes test results and makes them viewable directly in the CodeBuild console, including trends and detailed failure analysis. Option A (incorrect) manually downloading and analyzing logs is time-consuming and inefficient, especially for frequent builds. Option C (incorrect) while CloudWatch Logs Insights can query logs, it requires custom queries and doesn''t provide the structured test reporting and trend visualization that CodeBuild''s native feature offers. Option D (incorrect) integrating a third-party tool adds complexity and external dependencies, whereas CodeBuild offers this functionality natively.', 36, 'm_36_2', 16, NULL, NULL),
  ('mock_36_all_1775004784055', 'An organization manages its infrastructure using AWS CloudFormation templates. They need to ensure that the deployed infrastructure consistently matches the defined templates and detect any unauthorized or accidental changes that could lead to configuration drift. Which AWS service provides the MOST reliable detection of infrastructure configuration drift?', '["Manually compare the current state of resources with CloudFormation templates periodically.","Use AWS Config rules to monitor individual resource compliance.","Utilize AWS CloudFormation drift detection to identify differences between deployed stacks and templates.","Implement AWS CloudTrail to log all API calls and review them for unauthorized changes."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS CloudFormation drift detection. This feature directly compares the actual configuration of resources in a CloudFormation stack with the configuration defined in its template. It specifically identifies resources that have drifted from their expected state, providing the most reliable and direct method for detecting infrastructure configuration drift. Option A (incorrect) manual comparison is highly inefficient, error-prone, and not scalable. Option B (incorrect) AWS Config rules monitor compliance against desired configurations but are more general-purpose and don''t directly compare against CloudFormation templates in the same way as drift detection. Option D (incorrect) AWS CloudTrail logs API calls, which is crucial for auditing and security, but it requires significant effort to analyze logs to detect configuration drift and doesn''t provide a direct comparison against templates.', 36, 'm_36_2', 17, NULL, NULL),
  ('mock_36_all_1775004784055', 'A development team is building a complex microservices application. They need to implement a comprehensive testing strategy within their AWS CodePipeline that includes unit, integration, and end-to-end tests to catch issues at various levels before deployment. Which combination of AWS services and CodePipeline stages supports the MOST comprehensive automated testing strategy?', '["Use AWS CodeDeploy to run all tests during the deployment phase on production instances.","Execute all tests within a single AWS CodeBuild project in the build stage to save time.","Implement separate AWS CodeBuild actions within distinct CodePipeline stages for unit, integration, and end-to-end testing.","Integrate Amazon CodeGuru Reviewer for static analysis, and use AWS CodeBuild in dedicated stages for dynamic unit, integration, and end-to-end tests."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) provides the most comprehensive automated testing strategy. Integrating Amazon CodeGuru Reviewer early in the pipeline for static analysis catches potential issues before dynamic testing. Subsequently, using AWS CodeBuild in dedicated CodePipeline stages for unit, integration, and end-to-end tests allows for thorough validation at different levels of the application, ensuring quality throughout the SDLC. Option A (incorrect) running all tests during the deployment phase on production instances is an anti-pattern ([ap-1.2-001]) and highly risky, as it can impact live users and is too late in the cycle to efficiently catch and fix issues. Option B (incorrect) executing all tests in a single CodeBuild project can lead to long build times, make troubleshooting difficult, and doesn''t provide clear separation of concerns for different test types. Option C (incorrect) is a good start but doesn''t explicitly include static analysis, which is an important part of a comprehensive strategy.', 36, 'm_36_2', 18, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 18
