-- Module: m_38_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_36_all_1775004784055', 'A global SaaS provider needs to deploy its application across multiple AWS Regions to achieve maximum availability and low-latency access for users worldwide. The application consists of stateless web servers and a stateful database. They require an active-active setup with automatic traffic routing based on user proximity and endpoint health.', '["Implement AWS Global Accelerator to route user traffic to the nearest healthy regional endpoint, combined with Amazon Aurora Global Database for the stateful database.","Use Amazon Route 53 with latency routing policies to direct users to the closest region, and Amazon RDS Multi-AZ deployments in each region.","Configure Amazon CloudFront to cache content globally, and deploy the application in a single region with Amazon DynamoDB Global Tables.","Deploy the application in multiple regions and use a custom load balancing solution that periodically checks endpoint health and updates DNS records."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the optimal solution for maximum availability and low-latency active-active multi-region deployment. AWS Global Accelerator routes user traffic to the nearest healthy regional endpoint using the AWS global network, bypassing internet congestion and providing static IP addresses. Amazon Aurora Global Database is designed for global applications, providing low-latency global reads and fast disaster recovery with an RPO of seconds, making it ideal for the stateful database in an active-active setup. Option B (incorrect) Amazon Route 53 latency routing directs traffic based on perceived latency but does not inherently guarantee endpoint health without explicit health checks and failover policies, and it uses DNS, which can be subject to caching delays. Amazon RDS Multi-AZ is for single-region high availability, not cross-region active-active. Option C (incorrect) Amazon CloudFront is for content delivery and caching, not primary application traffic routing for dynamic applications. Deploying in a single region with DynamoDB Global Tables would address the database but not the application tier''s multi-region active-active requirement. Option D (incorrect) building a custom load balancing solution increases operational overhead, complexity, and potential for errors, which contradicts AWS best practices for leveraging managed services.', 38, 'm_38_1', 8, NULL, NULL),
  ('mock_36_all_1775004784055', 'A company hosts a critical web application on Amazon EC2 instances behind an Application Load Balancer in a single AWS Region. They want to enhance their disaster recovery posture by implementing a warm standby in a secondary region. Traffic should automatically fail over to the secondary region if the primary becomes unhealthy.', '["Configure Amazon Route 53 with a failover routing policy, using health checks on the primary region''s Application Load Balancer to direct traffic to the secondary region''s Application Load Balancer upon failure.","Use Amazon Route 53 with a latency routing policy to direct traffic to the region with the lowest latency, assuming the unhealthy primary region will naturally have higher latency.","Deploy AWS Global Accelerator to route traffic to the primary region, and manually update the accelerator''s endpoint group weights to shift traffic to the secondary region during a disaster.","Implement a custom script that continuously monitors the primary region''s health and updates the DNS records for the application to point to the secondary region if a failure is detected."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective and automated solution for warm standby failover. Amazon Route 53''s failover routing policy, combined with health checks on the primary region''s Application Load Balancer, will automatically detect unhealthiness and direct traffic to the pre-configured secondary region endpoint. This provides automated, reliable disaster recovery. Option B (incorrect) using Amazon Route 53 latency routing as a primary disaster recovery mechanism is an anti-pattern ([ap-3.1-001]). Latency routing prioritizes the lowest latency endpoint, not necessarily the healthiest. If the primary region is unhealthy but still reachable with low latency, traffic might continue to be routed there, leading to outages. Option C (incorrect) while AWS Global Accelerator can route traffic across regions, manually updating endpoint group weights during a disaster introduces manual intervention, increasing RTO and operational overhead, failing the ''automatically fail over'' requirement. Option D (incorrect) developing a custom script for DNS updates is complex, prone to errors, and increases operational overhead compared to Route 53''s managed failover policies.', 38, 'm_38_1', 9, NULL, NULL),
  ('mock_36_all_1775004784055', 'A gaming company needs to ensure its leaderboard data, stored in Amazon DynamoDB, is highly available and provides ultra-low latency reads and writes for players across different continents. The solution must support active-active replication and automatic conflict resolution.', '["Implement Amazon DynamoDB Global Tables across multiple AWS Regions.","Configure Amazon RDS Cross-Region Read Replicas for a PostgreSQL database in each region.","Use Amazon Aurora Global Database for a MySQL-compatible database deployed in multiple regions.","Deploy a single Amazon DynamoDB table in one region and use Amazon CloudFront to cache reads globally."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the ideal solution. Amazon DynamoDB Global Tables provide a fully managed, multi-region, multi-master database that delivers fast, local read and write performance for globally distributed applications. It automatically replicates data across specified AWS Regions and handles conflict resolution, ensuring active-active availability and ultra-low latency for global users. Option B (incorrect) Amazon RDS Cross-Region Read Replicas are for relational databases and primarily support read scaling and disaster recovery, not active-active multi-master writes with automatic conflict resolution across regions. Option C (incorrect) Amazon Aurora Global Database is a relational database solution for global applications, offering fast cross-region replication and failover. While it provides low-latency reads, DynamoDB Global Tables are purpose-built for the specific high-scale, low-latency, active-active NoSQL requirements often found in gaming leaderboards. Option D (incorrect) deploying a single DynamoDB table in one region would not provide ultra-low latency writes for global users, nor would it offer active-active availability across regions. CloudFront caches reads but doesn''t address write latency or regional availability for the primary data store.', 38, 'm_38_1', 10, NULL, NULL),
  ('mock_36_all_1775004784055', 'A media streaming service operates a multi-tier application with an Amazon Aurora MySQL database. To improve resilience and enable faster disaster recovery, they want to establish a multi-region architecture where the database can quickly fail over to a secondary region with minimal data loss (RPO in seconds) and provide read capacity in the secondary region during normal operations.', '["Configure Amazon Aurora Global Database, which provides fast cross-region replication and RPO in seconds, with a secondary cluster for reads.","Set up Amazon RDS Cross-Region Read Replicas for the Aurora database, promoting the replica during a disaster.","Use AWS Backup to create continuous backups of the Aurora database and replicate them to a secondary region.","Deploy a separate, independent Aurora cluster in a secondary region and use a custom application-level replication solution."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable solution. Amazon Aurora Global Database is specifically designed for global applications, offering RPO in seconds and fast recovery from regional outages. It maintains a primary cluster in one region and up to five secondary clusters in different regions, which can serve read traffic during normal operations and be promoted quickly in a disaster scenario. Option B (incorrect) Amazon RDS Cross-Region Read Replicas are not directly applicable to Aurora Global Database, as Aurora has its own global replication mechanism. While RDS Read Replicas can be promoted, Aurora Global Database offers superior RPO and RTO for cross-region disaster recovery for Aurora. Option C (incorrect) AWS Backup for Aurora can provide cross-region backups, but restoring from backups typically results in a higher RTO than ''minutes'' and does not provide read capacity in the secondary region during normal operations. Option D (incorrect) developing a custom application-level replication solution for a database is complex, error-prone, and increases operational overhead significantly compared to using a managed service like Aurora Global Database.', 38, 'm_38_1', 11, NULL, NULL),
  ('mock_36_all_1775004784055', 'A company has a public-facing API hosted on Amazon EC2 instances across multiple Availability Zones in a single region. They want to ensure that if an entire Availability Zone becomes unhealthy, traffic is automatically routed away from it to healthy Availability Zones.', '["Place the EC2 instances behind an Application Load Balancer (ALB) configured to distribute traffic across healthy targets in multiple Availability Zones.","Use Amazon Route 53 with health checks on individual EC2 instances and a multi-value answer routing policy.","Implement AWS Global Accelerator to route traffic to the healthy Availability Zones.","Configure AWS Fault Injection Service (FIS) to detect unhealthy Availability Zones and reroute traffic."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the standard and most effective solution for this scenario. An Application Load Balancer (ALB) automatically distributes incoming application traffic across multiple targets, such as EC2 instances, in multiple Availability Zones. It continuously monitors the health of its registered targets and routes traffic only to the healthy ones, ensuring that an unhealthy Availability Zone''s instances are automatically removed from rotation. Option B (incorrect) while Route 53 with health checks and multi-value answer routing can provide some level of AZ-aware routing, it operates at the DNS level and is less granular and responsive than an ALB for intra-region traffic distribution and health checks. It also requires more complex configuration for individual instance health checks. Option C (incorrect) AWS Global Accelerator is designed for global traffic management across AWS Regions, not for distributing traffic within a single region across Availability Zones. Option D (incorrect) AWS Fault Injection Service (FIS) is used for chaos engineering to proactively test resilience by injecting faults, not for real-time detection and rerouting of traffic from unhealthy Availability Zones in a production environment.', 38, 'm_38_1', 12, NULL, NULL),
  ('mock_36_all_1775004784055', 'An enterprise application uses Amazon RDS for PostgreSQL in a Multi-AZ deployment. To prepare for potential regional disasters, the DevOps team needs to implement a cross-region disaster recovery strategy that provides a recovery point objective (RPO) of minutes and allows the secondary region to serve read traffic during normal operations.', '["Configure Amazon RDS Cross-Region Read Replicas to a secondary region, which can be promoted to a standalone primary database during a disaster.","Migrate the database to Amazon Aurora Global Database for its built-in cross-region replication capabilities.","Use AWS Elastic Disaster Recovery (DRS) to continuously replicate the RDS database instance to a secondary region.","Implement AWS Backup to take hourly snapshots of the RDS database and copy them to a secondary region for restoration."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate solution for Amazon RDS PostgreSQL. Amazon RDS Cross-Region Read Replicas provide asynchronous replication to a secondary region, achieving an RPO of minutes. During normal operations, these replicas can serve read traffic, and in a disaster, they can be promoted to a standalone primary database, meeting the RTO and read traffic requirements. Option B (incorrect) migrating to Amazon Aurora Global Database would meet the RPO and read traffic requirements, but it involves a database engine migration from PostgreSQL to Aurora PostgreSQL-compatible, which is a significant architectural change and might not be feasible for an existing application. Option C (incorrect) AWS Elastic Disaster Recovery (DRS) is designed for server replication (EC2 instances, on-premises servers), not for managed database services like Amazon RDS. Option D (incorrect) using AWS Backup for hourly snapshots would provide an RPO of up to an hour, which is higher than ''minutes'', and restoring from snapshots typically results in a higher RTO than desired for rapid recovery.', 38, 'm_38_1', 13, NULL, NULL),
  ('mock_36_all_1775004784055', 'A global content delivery network needs to route user traffic to the optimal application endpoint across multiple AWS Regions, bypassing the congested public internet. The solution must provide static IP addresses and improve performance by leveraging the AWS global network backbone.', '["Implement AWS Global Accelerator to direct traffic to regional endpoints via the AWS global network, providing static Anycast IP addresses.","Configure Amazon Route 53 with a latency routing policy to direct users to the closest regional endpoint based on DNS resolution.","Utilize Amazon CloudFront to cache content at edge locations and serve requests from the nearest cache.","Deploy a custom VPN solution between regions to tunnel user traffic over a private network."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the ideal solution. AWS Global Accelerator improves application availability and performance for global users by routing traffic through the AWS global network backbone. It provides static Anycast IP addresses that act as a fixed entry point to your application endpoints in multiple AWS Regions, directing users to the optimal healthy endpoint, bypassing public internet congestion. Option B (incorrect) Amazon Route 53 latency routing directs traffic based on DNS resolution, which can be subject to caching and does not guarantee routing over the AWS global network backbone. It also doesn''t provide static Anycast IP addresses. Option C (incorrect) Amazon CloudFront is primarily a Content Delivery Network (CDN) for caching static and dynamic content at edge locations to reduce latency, but it''s not designed for routing primary application traffic across multiple regions via static IP addresses on the AWS backbone for performance optimization. Option D (incorrect) deploying a custom VPN solution is complex, increases operational overhead, and is not designed for public-facing global traffic routing for performance optimization; it''s typically used for secure private network connectivity.', 38, 'm_38_1', 14, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_38_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_36_all_1775004784055', 'A global IoT platform collects sensor data from millions of devices worldwide, requiring a database that can handle extremely high write volumes and provide low-latency reads globally. The solution must automatically scale to accommodate fluctuating loads and maintain high availability across multiple regions.', '["Implement Amazon DynamoDB Global Tables to provide multi-region, active-active replication with automatic scaling for reads and writes.","Configure Amazon Aurora Global Database with a primary region for writes and read replicas in secondary regions for global reads.","Deploy Amazon RDS Multi-AZ instances in each region and use Route 53 latency routing to direct traffic.","Use AWS Backup to replicate a single-region Amazon DynamoDB table to other regions for disaster recovery purposes."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable solution. Amazon DynamoDB Global Tables are specifically designed for globally distributed applications requiring ultra-low latency reads and writes, high availability, and automatic scaling to handle massive, fluctuating workloads. Its multi-region, active-active replication with automatic conflict resolution perfectly fits the requirements of a global IoT platform. Option B (incorrect) Amazon Aurora Global Database is excellent for global relational workloads, offering low-latency reads from secondary regions and fast failover. However, for ''extremely high write volumes'' and the NoSQL nature often associated with IoT sensor data, DynamoDB''s native scaling for writes and its schema-less design are typically a better fit. Option C (incorrect) Amazon RDS Multi-AZ instances provide high availability within a single region, not multi-region active-active scaling for global reads and writes. Route 53 latency routing alone is insufficient for an active-active database solution. Option D (incorrect) AWS Backup is a disaster recovery solution, not a mechanism for providing active-active, low-latency global reads and writes for a production workload. It would not meet the performance or availability requirements.', 38, 'm_38_2', 15, NULL, NULL),
  ('mock_36_all_1775004784055', 'A multinational corporation needs to distribute its internal web application to employees located in various continents. The application uses an Amazon Aurora MySQL database. They require a solution that ensures low-latency access for all users and automatically scales database read capacity across regions to meet demand.', '["Configure Amazon Aurora Global Database, leveraging its secondary clusters for read scaling and fast cross-region failover.","Deploy Amazon RDS Cross-Region Read Replicas for the Aurora database in each continent, and use Route 53 latency routing.","Implement AWS Global Accelerator to route user traffic to the nearest application endpoint, with a single Aurora database in the primary region.","Use Amazon DynamoDB Global Tables to store application data, as it provides global read/write capabilities and automatic scaling."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate solution. Amazon Aurora Global Database is designed for global applications, providing low-latency reads from secondary clusters in different regions. These secondary clusters automatically scale their read capacity, meeting the demand for global read scaling. It also offers an RPO of seconds for disaster recovery, ensuring high availability. Option B (incorrect) while Amazon RDS Cross-Region Read Replicas can provide read scaling and DR, Aurora Global Database offers superior performance, RPO, and management for a global Aurora deployment. The question specifically mentions an Aurora database. Option C (incorrect) AWS Global Accelerator routes user traffic to the nearest application endpoint, which helps with application latency, but it does not inherently scale the database read capacity across regions. A single Aurora database in the primary region would become a bottleneck for global read demand. Option D (incorrect) Amazon DynamoDB Global Tables are a NoSQL solution. The scenario specifies an Amazon Aurora MySQL database, implying a relational database requirement. Migrating to DynamoDB would be a significant architectural change.', 38, 'm_38_2', 16, NULL, NULL),
  ('mock_36_all_1775004784055', 'A public-facing API serves millions of requests per second globally. The API backend is deployed across multiple AWS Regions. The DevOps team needs a mechanism to intelligently route user traffic to the nearest healthy regional endpoint, ensuring optimal performance and scalability of traffic distribution.', '["Implement AWS Global Accelerator to route traffic to the nearest healthy regional endpoint using the AWS global network backbone.","Configure Amazon Route 53 with a latency routing policy to direct users to the region with the lowest perceived latency.","Utilize Amazon CloudFront to cache API responses at edge locations, reducing the load on regional API backends.","Deploy a custom proxy server in each region to forward requests to the most performant backend based on real-time metrics."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective solution for intelligent, performant, and scalable global traffic distribution. AWS Global Accelerator uses the AWS global network backbone to route user traffic to the nearest healthy regional endpoint, bypassing public internet congestion and providing static Anycast IP addresses. This ensures optimal performance and scalability of traffic distribution for millions of requests per second. Option B (incorrect) Amazon Route 53 latency routing directs traffic based on DNS resolution, which can be subject to caching and does not guarantee routing over the AWS global network backbone. While it aims for low latency, Global Accelerator offers superior performance and resilience for global applications. Option C (incorrect) Amazon CloudFront is a Content Delivery Network (CDN) primarily for caching and serving static/dynamic content. While it can reduce load, it''s not the primary mechanism for routing live API traffic to the ''nearest healthy regional endpoint'' using static IPs and the AWS backbone for performance optimization. Option D (incorrect) deploying custom proxy servers increases operational overhead, complexity, and maintenance burden. AWS Global Accelerator provides this functionality as a managed service.', 38, 'm_38_2', 17, NULL, NULL),
  ('mock_36_all_1775004784055', 'A company''s critical application uses Amazon DynamoDB as its primary data store. Due to anticipated global growth, they need to ensure the database can scale to handle increasing read and write throughput from users worldwide, while maintaining an active-active setup for continuous availability.', '["Configure Amazon DynamoDB Global Tables across multiple AWS Regions to provide multi-master replication and automatic scaling.","Implement Amazon Aurora Global Database for a relational database, leveraging its cross-region replication and read scaling capabilities.","Use Amazon RDS Cross-Region Read Replicas for a PostgreSQL database, promoting a replica during a disaster.","Deploy a single Amazon DynamoDB table in a primary region and manually provision additional read/write capacity units as needed."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the ideal solution. Amazon DynamoDB Global Tables are designed for global applications requiring active-active, multi-region replication. They automatically scale read and write throughput across regions, providing low-latency access and continuous availability for users worldwide, perfectly matching the requirement for global growth and active-active setup. Option B (incorrect) Amazon Aurora Global Database is a relational database solution. The scenario explicitly states Amazon DynamoDB as the primary data store, implying a NoSQL requirement. Migrating to Aurora would be a significant architectural change. Option C (incorrect) Amazon RDS Cross-Region Read Replicas are for relational databases and primarily support read scaling and disaster recovery, not active-active multi-master writes with automatic conflict resolution across regions. Option D (incorrect) deploying a single DynamoDB table in a primary region and manually provisioning capacity would not provide multi-region active-active availability or low-latency access for global users. Manual scaling also increases operational overhead and can lead to performance bottlenecks during unexpected spikes in demand.', 38, 'm_38_2', 18, NULL, NULL),
  ('mock_36_all_1775004784055', 'A global analytics platform processes real-time data streams. The platform''s front-end is served from multiple AWS Regions. The DevOps team needs to ensure that DNS queries are resolved efficiently and traffic is directed to the healthiest and most performant regional endpoint, scaling with user demand.', '["Configure Amazon Route 53 with health checks and various routing policies (e.g., latency, weighted, failover) to direct users to optimal regional endpoints.","Implement AWS Global Accelerator to route traffic to the nearest healthy endpoint via the AWS global network backbone, providing static IP addresses.","Utilize Amazon CloudFront to distribute and cache content globally, reducing latency for static assets.","Deploy a custom DNS server in each region to handle local query resolution and traffic distribution."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most comprehensive solution for efficient DNS query resolution and directing traffic to the healthiest and most performant regional endpoint, scaling with user demand. Amazon Route 53 offers various routing policies (latency, weighted, failover, geolocation) combined with health checks. This allows for intelligent DNS-based traffic management to ensure users are directed to the best available regional endpoint. Option B (incorrect) AWS Global Accelerator is excellent for routing traffic over the AWS backbone and providing static IPs, which improves performance and resilience. However, the question specifically mentions ''DNS queries are resolved efficiently'' and Route 53 is the primary DNS service. While Global Accelerator can be used in conjunction with Route 53, Route 53 itself provides the core DNS resolution and policy-based routing. Option C (incorrect) Amazon CloudFront is a Content Delivery Network (CDN) primarily for caching and serving static/dynamic content, not for directing primary application traffic or resolving DNS queries for backend services. Option D (incorrect) deploying custom DNS servers is complex, increases operational overhead, and is generally not recommended over using a managed service like Amazon Route 53 for global DNS resolution and traffic management.', 38, 'm_38_2', 19, NULL, NULL),
  ('mock_36_all_1775004784055', 'A financial trading application requires extremely low-latency access to its database from multiple geographic locations. The database must be able to scale its read capacity to support high-frequency queries from traders globally, while maintaining strong consistency for writes.', '["Implement Amazon Aurora Global Database, utilizing its secondary clusters for low-latency global reads and fast recovery.","Configure Amazon DynamoDB Global Tables for multi-region active-active read/write access with automatic scaling.","Deploy Amazon RDS Cross-Region Read Replicas for a PostgreSQL database, promoting a replica during a disaster.","Use AWS Global Accelerator to route application traffic to a single-region Amazon Aurora database."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable solution. Amazon Aurora Global Database provides a globally distributed relational database with RPO in seconds. Its secondary clusters in different regions can serve extremely low-latency read requests from traders globally and automatically scale read capacity, while maintaining strong consistency for writes directed to the primary region. This meets all specified requirements for a financial trading application. Option B (incorrect) Amazon DynamoDB Global Tables provide multi-region active-active read/write access and automatic scaling, but it is a NoSQL database. Financial trading applications often rely on relational databases for strong consistency and complex transactional queries, which Aurora provides. Option C (incorrect) Amazon RDS Cross-Region Read Replicas can provide read scaling and disaster recovery, but Aurora Global Database offers superior performance, RPO, and management for a global relational database with extremely low-latency requirements. Option D (incorrect) AWS Global Accelerator routes application traffic, but it does not solve the database''s scaling or low-latency access problem from multiple geographic locations if the database is only in a single region. A single-region database would be a bottleneck for global read capacity and latency.', 38, 'm_38_2', 20, NULL, NULL);

