INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_36_all_1775004784055', 'A large enterprise needs to ensure all new Amazon EC2 instances across multiple AWS accounts are continuously scanned for software vulnerabilities and deviations from security best practices, with findings aggregated centrally. The solution must minimize operational overhead for security teams.', '["Deploy Amazon Inspector v2 for continuous scanning and integrate its findings with AWS Security Hub for centralized aggregation and compliance checks.","Manually install and configure open-source vulnerability scanning tools on each Amazon EC2 instance and export findings to a custom dashboard.","Use AWS Config rules to detect non-compliant Amazon EC2 instance configurations and send notifications to Amazon SNS, then manually review.","Implement AWS GuardDuty for threat detection on Amazon EC2 instances and use its findings for vulnerability management."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most automated and low-overhead solution. Amazon Inspector v2 offers continuous, automated vulnerability scanning for Amazon EC2 instances and container images. Integrating its findings with AWS Security Hub centralizes security findings and allows for compliance checks against standards, significantly minimizing operational overhead. Option B (incorrect) represents a manual approach that would incur significant operational overhead and is prone to errors, directly conflicting with the ''LEAST operational overhead'' constraint. Option C (incorrect) focuses on configuration compliance rather than continuous software vulnerability scanning, and requires manual review, which is not optimal for minimizing overhead. Option D (incorrect) is primarily for threat detection and malicious activity, not for continuous software vulnerability scanning of instances, making it unsuitable for the core requirement.', 41, 'm_41_2', 1, NULL, NULL),
  ('mock_36_all_1775004784055', 'A development team uses a third-party API key stored in AWS Secrets Manager for their application. The security policy requires this key to be rotated every 90 days without application downtime or manual intervention. Which approach meets this requirement with the LEAST operational overhead?', '["Configure AWS Secrets Manager automatic rotation with a custom AWS Lambda rotation function.","Manually rotate the API key every 90 days by updating the secret in AWS Secrets Manager and redeploying the application.","Implement a cron job on an Amazon EC2 instance to periodically call the Secrets Manager API to update the secret.","Store the API key in an Amazon S3 bucket encrypted with AWS KMS and update it via a script."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective and low-overhead solution. AWS Secrets Manager natively supports automatic rotation of secrets, including custom secrets, by invoking an AWS Lambda function. This function can be configured to rotate the API key without manual intervention or application downtime, directly addressing the requirement. Option B (incorrect) represents the anti-pattern of manually rotating credentials, which is error-prone, time-consuming, and does not meet the ''without manual intervention'' constraint. Option C (incorrect) introduces an additional Amazon EC2 instance to manage, increasing operational overhead and complexity compared to the native Secrets Manager feature. Option D (incorrect) is not a secure or automated way to manage and rotate API keys; Amazon S3 is not designed for secret management and lacks native rotation capabilities.', 41, 'm_41_2', 2, NULL, NULL),
  ('mock_36_all_1775004784055', 'A company processes sensitive customer data in Amazon S3 buckets. They need to automatically discover, classify, and protect this data to meet compliance requirements, while also detecting potential threats related to data access patterns. Which combination of services provides the MOST comprehensive automated solution?', '["Utilize Amazon Macie for data discovery and classification, Amazon GuardDuty for threat detection on S3 access, and AWS KMS for encryption.","Implement AWS Config rules to check S3 bucket policies and use AWS Security Hub to aggregate findings.","Manually review S3 bucket contents for sensitive data and enable S3 server access logging for auditing.","Encrypt S3 buckets with server-side encryption and use AWS IAM Access Analyzer to identify external access."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) offers the most comprehensive automated solution. Amazon Macie is specifically designed to discover, classify, and protect sensitive data in Amazon S3, including PII. Amazon GuardDuty provides intelligent threat detection for S3 access patterns, identifying unusual or potentially malicious activity. AWS KMS ensures data is encrypted at rest, fulfilling the protection aspect. This combination directly addresses all parts of the requirement. Option B (incorrect) focuses on S3 bucket policy compliance and aggregation of findings, but does not provide automated data classification or advanced threat detection on access patterns. Option C (incorrect) involves manual processes, which is inefficient and error-prone, failing the ''automatically'' constraint. Option D (incorrect) provides encryption and identifies external access, but lacks automated data classification and comprehensive threat detection on access patterns.', 41, 'm_41_2', 3, NULL, NULL),
  ('mock_36_all_1775004784055', 'An organization wants to enforce a preventive control that disallows the creation of Amazon S3 buckets with public read/write access across all accounts within their AWS Organization. This policy must apply to all existing and future accounts and be centrally managed. What is the MOST effective solution?', '["Implement an AWS Organizations Service Control Policy (SCP) to deny the `s3:PutBucketPublicAccessBlock` action if public access is not blocked.","Configure Amazon S3 Block Public Access settings at the account level in each member account.","Deploy an AWS Lambda function triggered by AWS Config rules to remediate any publicly accessible S3 buckets.","Use AWS IAM policies in each account to prevent users from creating public S3 buckets."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective preventive control. An AWS Organizations Service Control Policy (SCP) can centrally enforce restrictions across all accounts in an organization, including new accounts. By denying actions that would allow public S3 access, it acts as a guardrail that cannot be overridden by individual account administrators. Option B (incorrect) requires manual configuration in each account and does not automatically apply to new accounts, making it less scalable and prone to human error. Option C (incorrect) is a detective and reactive control (remediation after creation) rather than a preventive one, which is less ideal for preventing public access from the outset. Option D (incorrect) relies on IAM policies within each account, which can be circumvented by administrative users in those accounts and does not provide a central, unoverridable control across the entire organization.', 41, 'm_41_2', 4, NULL, NULL),
  ('mock_36_all_1775004784055', 'A security team wants to centralize all security findings from various AWS services like Amazon GuardDuty and Amazon Inspector into a single dashboard for easier monitoring and remediation tracking. They also need to check compliance against industry standards. Which service combination provides this capability with the LEAST integration effort?', '["Use AWS Security Hub to aggregate findings from Amazon GuardDuty and Amazon Inspector, and enable compliance standards.","Create custom Amazon CloudWatch dashboards to display findings from each service individually.","Export findings from Amazon GuardDuty and Amazon Inspector to Amazon S3, then process them with AWS Lambda for a custom visualization.","Configure AWS Config conformance packs to define security standards and use AWS Audit Manager for evidence collection."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is designed precisely for this purpose. AWS Security Hub automatically aggregates security findings from various AWS services, including Amazon GuardDuty and Amazon Inspector, into a single, centralized view. It also allows enabling compliance standards (e.g., CIS Benchmarks, PCI DSS) for automated checks, requiring minimal integration effort. Option B (incorrect) would require significant manual effort to create and maintain separate dashboards for each service, and would not natively provide compliance checks. Option C (incorrect) involves a complex custom solution with Amazon S3 and AWS Lambda, which increases operational overhead and integration effort. Option D (incorrect) focuses on compliance deployment and audit evidence collection, but does not provide a centralized dashboard for real-time security findings from services like GuardDuty and Inspector.', 41, 'm_41_2', 5, NULL, NULL),
  ('mock_36_all_1775004784055', 'A DevOps team needs to ensure that all data stored in Amazon S3 for their critical application is encrypted at rest using customer-managed keys, and that the encryption key itself is securely managed and rotated automatically. What is the MOST appropriate solution?', '["Use Amazon S3 server-side encryption with AWS Key Management Service (AWS KMS) customer-managed keys (CMKs) and enable automatic key rotation for the CMK.","Implement client-side encryption for data uploaded to Amazon S3, managing encryption keys within the application code.","Encrypt data using a custom encryption library before uploading to Amazon S3 and store the encryption key in AWS Secrets Manager, rotating it manually.","Configure Amazon S3 server-side encryption with S3-managed keys (SSE-S3) and rely on AWS to manage key rotation."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate solution. Amazon S3 server-side encryption with AWS KMS customer-managed keys (CMKs) allows the team to use their own keys while leveraging the managed service for encryption. AWS KMS CMKs can be configured for automatic annual key rotation, fulfilling the requirement for secure, automated key management. Option B (incorrect) shifts the burden of key management and rotation entirely to the application, increasing complexity and operational overhead. Option C (incorrect) involves manual key rotation, which is an anti-pattern and does not meet the ''rotated automatically'' constraint. Option D (incorrect) uses S3-managed keys, which are not customer-managed, failing the ''customer-managed keys'' requirement.', 41, 'm_41_2', 6, NULL, NULL),
  ('mock_36_all_1775004784055', 'A financial institution needs to implement continuous compliance monitoring for their AWS resources to ensure they adhere to PCI DSS standards. They require automated detection of non-compliant resources and aggregation of these findings into a central security dashboard. Which combination of services is MOST suitable?', '["Deploy AWS Config conformance packs for PCI DSS and integrate findings with AWS Security Hub for centralized monitoring.","Perform manual compliance audits quarterly and use AWS Audit Manager to collect evidence.","Use AWS GuardDuty for continuous threat detection and send findings to Amazon CloudWatch for alerts.","Implement AWS Organizations Service Control Policies (SCPs) to prevent non-compliant resource creation."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable for continuous compliance monitoring. AWS Config conformance packs allow for deploying a collection of AWS Config rules and remediation actions to check for compliance against standards like PCI DSS. AWS Security Hub then aggregates these compliance findings, along with security findings from other services, into a central dashboard, providing continuous monitoring. Option B (incorrect) represents the anti-pattern of performing compliance audits manually, which is not continuous and discovers issues after they have been present for months, increasing risk exposure. Option C (incorrect) is focused on threat detection, not compliance against specific standards or automated detection of non-compliant resource configurations. Option D (incorrect) provides preventive controls, which are valuable, but does not offer continuous monitoring and detection of non-compliant resources that may already exist or drift out of compliance.', 41, 'm_41_2', 7, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_41_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_36_all_1775004784055', 'A security team needs to continuously monitor for potential threats and malicious activity within their AWS environment, including unusual API calls, unauthorized access, and compromised instances. Findings must be actionable and integrated with a central security dashboard. Which service combination provides the MOST effective continuous threat detection?', '["Enable Amazon GuardDuty for intelligent threat detection and stream its findings to AWS Security Hub for centralized aggregation.","Manually review AWS CloudTrail logs and Amazon VPC Flow Logs daily for suspicious activity.","Deploy Amazon Inspector v2 for vulnerability scanning and use AWS Config to monitor resource configurations.","Utilize AWS IAM Access Analyzer to identify external access and send alerts via Amazon SNS."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most effective continuous threat detection. Amazon GuardDuty is a managed threat detection service that continuously monitors for malicious activity and unauthorized behavior. Integrating its findings with AWS Security Hub centralizes these actionable insights, allowing for a consolidated view of the security posture. Option B (incorrect) involves manual review, which is an anti-pattern for continuous monitoring, highly inefficient, and prone to missing critical events. Option C (incorrect) focuses on vulnerability scanning and configuration compliance, not real-time threat detection for malicious activity. Option D (incorrect) is designed to identify external and unused access, which is a security control, but not a comprehensive threat detection service for ongoing malicious activity.', 41, 'm_41_3', 8, NULL, NULL),
  ('mock_36_all_1775004784055', 'An organization wants to identify all external entities that have access to their AWS resources and also detect any unused access permissions within their IAM roles and users. This is crucial for maintaining a strong security posture and adhering to the principle of least privilege. Which service is purpose-built for this task?', '["AWS IAM Access Analyzer.","AWS Config.","Amazon GuardDuty.","AWS Security Hub."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is purpose-built for this task. AWS IAM Access Analyzer helps identify resources shared with an external entity and also identifies unused access (unused roles, unused services, unused actions) within IAM. This directly addresses the requirement for identifying external and unused access to enforce the principle of least privilege. Option B (incorrect) is used for assessing, auditing, and evaluating the configurations of AWS resources, not specifically for analyzing IAM access policies for external or unused access. Option C (incorrect) is a threat detection service that monitors for malicious activity and unauthorized behavior, not for analyzing IAM policies for access patterns. Option D (incorrect) is a central hub for security findings and compliance status, it aggregates findings but doesn''t perform the deep IAM access analysis itself.', 41, 'm_41_3', 9, NULL, NULL),
  ('mock_36_all_1775004784055', 'A company needs to automate the collection of audit evidence for various compliance frameworks (e.g., SOC 2, HIPAA) across their AWS accounts. The solution should simplify the audit process by continuously gathering relevant data and organizing it for auditors. Which AWS service is designed for this specific purpose?', '["AWS Audit Manager.","AWS Config.","AWS CloudTrail.","AWS Security Hub."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is specifically designed for automating audit evidence collection. AWS Audit Manager helps continuously audit your AWS usage to simplify how you assess risk and compliance with regulations and industry standards. It collects evidence automatically and organizes it according to your chosen framework. Option B (incorrect) is used for assessing, auditing, and evaluating the configurations of AWS resources, and can be a source of evidence for Audit Manager, but it doesn''t automate the entire evidence collection and organization process for specific frameworks. Option C (incorrect) provides a record of actions taken by a user, role, or an AWS service, which is a source of audit data, but it doesn''t automate the collection and organization of evidence for compliance frameworks. Option D (incorrect) aggregates security findings and compliance status, but it is not primarily an audit evidence collection and organization tool.', 41, 'm_41_3', 10, NULL, NULL),
  ('mock_36_all_1775004784055', 'A DevOps team is responsible for ensuring that all Amazon EC2 instances and container images deployed in their environment are free from known software vulnerabilities. They need a solution that provides continuous, automated scanning and reports findings centrally to their security team. Which service combination is MOST appropriate?', '["Implement Amazon Inspector v2 for continuous vulnerability scanning and integrate findings with AWS Security Hub.","Manually run vulnerability scans on Amazon EC2 instances using third-party tools on a quarterly basis.","Use AWS Config rules to check if Amazon EC2 instances have specific security agents installed.","Enable Amazon GuardDuty to detect unusual network activity and potential compromises on instances."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate solution. Amazon Inspector v2 provides continuous, automated vulnerability scanning for Amazon EC2 instances and container images. Integrating its findings with AWS Security Hub centralizes these reports for the security team, enabling efficient monitoring and remediation. Option B (incorrect) represents a manual, periodic approach (an anti-pattern) that is inefficient, error-prone, and does not provide continuous scanning. Option C (incorrect) checks for the presence of agents, which is a compliance check, but does not perform actual vulnerability scanning of the software on the instances. Option D (incorrect) is a threat detection service, not a vulnerability management service for identifying known software flaws.', 41, 'm_41_3', 11, NULL, NULL),
  ('mock_36_all_1775004784055', 'A security engineer wants to ensure that all AWS resource configurations adhere to specific internal security policies and regulatory standards. They need to automatically detect and report any configuration drift from these defined baselines. Which AWS service is best suited for this continuous monitoring task?', '["AWS Config.","AWS CloudTrail.","Amazon GuardDuty.","AWS IAM Access Analyzer."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is best suited for continuous configuration monitoring. AWS Config continuously monitors and records your AWS resource configurations and allows you to automate the evaluation of recorded configurations against desired baselines. It can detect and report any configuration drift from defined policies and standards. Option B (incorrect) records API activity and events, which is useful for auditing, but does not continuously evaluate resource configurations against baselines. Option C (incorrect) is a threat detection service that monitors for malicious activity, not configuration compliance. Option D (incorrect) identifies external and unused access to resources, which is an IAM security control, not a general resource configuration monitoring service.', 41, 'm_41_3', 12, NULL, NULL),
  ('mock_36_all_1775004784055', 'A company requires a centralized view of its security posture across multiple AWS accounts, including aggregated findings from various security services and compliance checks against predefined standards. The solution should also allow for custom insights and automation of responses. Which service is designed to fulfill this requirement?', '["AWS Security Hub.","Amazon CloudWatch.","AWS Organizations.","Amazon Inspector v2."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is specifically designed for this purpose. AWS Security Hub provides a comprehensive view of your high-priority security alerts and compliance status across AWS accounts. It aggregates findings from various AWS security services (like GuardDuty, Macie, Inspector, Config) and allows for compliance checks against industry standards. It also supports custom insights and integration with automation tools. Option B (incorrect) is a monitoring and observability service, but it does not natively aggregate security findings from multiple services into a security-focused dashboard with compliance checks. Option C (incorrect) is used for centralizing management of multiple AWS accounts, but it does not provide a security posture dashboard. Option D (incorrect) is a vulnerability management service for EC2 and containers; it provides findings but not the centralized aggregation and compliance checks across multiple services.', 41, 'm_41_3', 13, NULL, NULL),
  ('mock_36_all_1775004784055', 'A DevOps team needs to ensure that all sensitive data stored in Amazon S3 buckets is continuously monitored for potential PII exposure and unusual access patterns. Findings should be integrated into their existing security operations dashboard. Which combination of services provides the MOST effective continuous monitoring?', '["Enable Amazon Macie for PII detection and Amazon GuardDuty for S3 threat detection, sending all findings to AWS Security Hub.","Configure S3 bucket policies to deny public access and enable S3 server access logging for manual review.","Use AWS Config rules to monitor S3 bucket encryption status and send notifications to Amazon SNS.","Implement AWS IAM Access Analyzer to identify external access to S3 buckets and generate reports."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most effective continuous monitoring. Amazon Macie is specifically designed to discover and protect sensitive data, including PII, in Amazon S3. Amazon GuardDuty offers intelligent threat detection for S3, identifying unusual access patterns. Integrating both services'' findings into AWS Security Hub provides a centralized, continuous view for the security operations dashboard. Option B (incorrect) focuses on preventing public access and provides logs for manual review, which is not continuous or automated for PII detection or unusual access patterns. Option C (incorrect) monitors encryption status, which is a security control, but does not detect PII exposure or unusual access patterns. Option D (incorrect) identifies external access, which is a valuable security control, but does not perform continuous PII detection or comprehensive threat detection on S3 access patterns.', 41, 'm_41_3', 14, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_41_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_36_all_1775004784055', 'A large organization with multiple AWS accounts wants to enforce a strict "deny by default" policy for specific high-risk actions, such as disabling AWS CloudTrail or deleting AWS KMS keys, across all member accounts. This policy must be centrally managed and cannot be overridden by individual account administrators. What is the MOST effective solution?', '["Implement an AWS Organizations Service Control Policy (SCP) to explicitly deny the high-risk actions.","Apply restrictive AWS IAM policies to all users and roles in each member account.","Use AWS Config rules to detect when high-risk actions are performed and trigger remediation.","Configure AWS Security Hub to alert on high-risk actions and manually intervene."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective solution. AWS Organizations Service Control Policies (SCPs) allow central management of permissions across all accounts in an organization. An SCP acts as a guardrail, defining the maximum available permissions for any IAM entity in member accounts, and cannot be overridden by individual account administrators, ensuring a strict ''deny by default'' for specified high-risk actions. Option B (incorrect) relies on individual IAM policies, which can be overridden or modified by administrators within those accounts, failing the ''cannot be overridden'' constraint. Option C (incorrect) is a detective and reactive control; it detects after the action has occurred, rather than preventing it. Option D (incorrect) is a monitoring solution that requires manual intervention, which does not provide a preventive, unoverridable control.', 41, 'm_41_1', 15, NULL, NULL),
  ('mock_36_all_1775004784055', 'A software development team uses database credentials for their application that are stored in AWS Secrets Manager. To enhance security and comply with internal policies, these credentials must be automatically rotated every 60 days without requiring manual intervention or application code changes. Which approach best meets these requirements?', '["Configure AWS Secrets Manager automatic rotation using a provided or custom AWS Lambda rotation function.","Manually update the credentials in AWS Secrets Manager every 60 days and notify the application to refresh.","Store credentials in Amazon S3 encrypted with AWS KMS and write a custom script to rotate them.","Use AWS IAM roles for Amazon EC2 instances to access the database directly, eliminating the need for credentials."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best approach. AWS Secrets Manager provides native support for automatic rotation of database credentials using pre-built or custom AWS Lambda rotation functions. This ensures credentials are rotated on a defined schedule (e.g., every 60 days) without manual intervention or requiring application code changes, as the application retrieves the latest secret value from Secrets Manager. Option B (incorrect) represents the anti-pattern of manual credential rotation, which is error-prone and does not meet the ''automatically rotated without manual intervention'' constraint. Option C (incorrect) involves a custom solution that increases operational overhead and Amazon S3 is not designed for secret management. Option D (incorrect) is a good practice for EC2 instances to access AWS services, but it does not apply to third-party databases or services that require specific credentials to be managed and rotated.', 41, 'm_41_1', 16, NULL, NULL),
  ('mock_36_all_1775004784055', 'A security architect needs to ensure that developers in a specific AWS account cannot grant themselves or others permissions to access sensitive data in Amazon S3, even if their IAM role has broad administrative privileges. This must be a preventive control that restricts the maximum permissions. What is the MOST effective method?', '["Attach an IAM permissions boundary to the developers'' IAM roles that explicitly denies access to sensitive S3 buckets.","Implement an AWS Organizations Service Control Policy (SCP) to deny access to sensitive S3 buckets for the entire account.","Regularly audit IAM policies using AWS IAM Access Analyzer and remediate overly permissive policies.","Configure Amazon S3 bucket policies to deny access to specific sensitive buckets for all IAM users and roles."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective preventive control for this scenario. An IAM permissions boundary defines the maximum permissions that an IAM entity (user or role) can have. Even if an administrator attaches a broad IAM policy to a developer''s role, the effective permissions are limited by the permissions boundary, preventing them from granting themselves access to sensitive S3 data. Option B (incorrect) would deny access for the entire account, which is too broad if other roles legitimately need access to those S3 buckets. Option C (incorrect) is a detective control, identifying issues after they occur, rather than preventing them. Option D (incorrect) would deny access to specific buckets, but an administrator with broad privileges could potentially modify the bucket policy itself, circumventing the control.', 41, 'm_41_1', 17, NULL, NULL),
  ('mock_36_all_1775004784055', 'An organization needs to regularly review and identify any IAM roles or users that have been granted permissions but have not been used for an extended period. This is part of their least privilege enforcement strategy. Which AWS service can automate the identification of these unused access findings?', '["AWS IAM Access Analyzer.","AWS Config.","AWS CloudTrail.","AWS Security Hub."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is specifically designed to automate the identification of unused access. AWS IAM Access Analyzer helps you identify unused access for IAM roles, users, and access keys. It provides findings for unused roles, unused services, and unused actions, which is critical for enforcing the principle of least privilege. Option B (incorrect) monitors resource configurations and compliance, but does not specifically analyze IAM usage for unused permissions. Option C (incorrect) records API activity, which can be used to manually infer usage, but it does not automate the identification of unused access itself. Option D (incorrect) aggregates security findings and compliance status, but it relies on other services like IAM Access Analyzer to generate the unused access findings.', 41, 'm_41_1', 18, NULL, NULL),
  ('mock_36_all_1775004784055', 'A company has a multi-account AWS environment and wants to ensure that all external access to their Amazon S3 buckets and AWS KMS keys is immediately identified and reported. This is critical for preventing data exfiltration and unauthorized cryptographic operations. Which service provides the MOST efficient way to detect and report this external access?', '["AWS IAM Access Analyzer, with findings integrated into AWS Security Hub.","Manually review Amazon S3 bucket policies and AWS KMS key policies across all accounts.","Configure AWS Config rules to check for public S3 buckets and KMS key policies.","Enable Amazon GuardDuty to detect unusual API calls to S3 and KMS."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most efficient way to detect and report external access. AWS IAM Access Analyzer continuously monitors resource policies (including S3 bucket policies and KMS key policies) to identify resources that are shared with an external entity. Integrating these findings into AWS Security Hub centralizes them for immediate reporting and action. Option B (incorrect) involves manual review, which is inefficient, error-prone, and not scalable across multiple accounts. Option C (incorrect) focuses on configuration compliance and can detect public access, but IAM Access Analyzer is purpose-built for comprehensive external access analysis. Option D (incorrect) detects unusual API calls, which is a threat detection mechanism, but not specifically designed to identify all external access granted via resource policies.', 41, 'm_41_1', 19, NULL, NULL),
  ('mock_36_all_1775004784055', 'A DevOps team manages several applications that connect to third-party services using API keys. These keys are currently hardcoded in application configurations. The team needs to migrate these keys to a secure, centralized store and implement automated rotation. Which solution offers the LEAST operational overhead?', '["Migrate API keys to AWS Secrets Manager and configure automatic rotation with an AWS Lambda rotation function.","Store API keys in an encrypted Amazon S3 bucket and implement a custom key rotation mechanism using Amazon EventBridge and AWS Lambda.","Embed API keys directly into AWS Lambda environment variables and manually update them as needed.","Use AWS Systems Manager Parameter Store to store API keys and develop a custom rotation solution."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) offers the least operational overhead. AWS Secrets Manager is a dedicated service for managing and rotating secrets, including API keys. Its native integration with AWS Lambda for automatic rotation eliminates the need for manual intervention or complex custom solutions, providing a secure and centralized store. Option B (incorrect) involves building a custom solution for storage and rotation, which significantly increases operational overhead compared to a managed service like Secrets Manager. Option C (incorrect) is not a centralized store, and manual updates are an anti-pattern for secret rotation, increasing risk and overhead. Option D (incorrect) can store secrets, but its native rotation capabilities are more limited than Secrets Manager, requiring more custom development for automated rotation, thus increasing operational overhead.', 41, 'm_41_1', 20, NULL, NULL),
  ('mock_36_all_1775004784055', 'A security team wants to define a maximum set of permissions that an IAM role can ever have, regardless of the policies attached to it. This is to ensure that even if an administrator mistakenly attaches an overly permissive policy, the role''s effective permissions remain restricted. Which IAM feature should be used?', '["IAM permissions boundaries.","AWS Organizations Service Control Policies (SCPs).","IAM condition keys.","IAM roles trust policies."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the specific IAM feature designed for this purpose. An IAM permissions boundary is an advanced feature for setting the maximum permissions that an identity-based policy can grant to an IAM entity. Even if an administrator attaches a more permissive policy, the permissions boundary ensures the effective permissions never exceed the boundary. Option B (incorrect) applies to accounts within an AWS Organization, defining maximum permissions for all IAM entities in those accounts, but it doesn''t apply to individual IAM roles within an account in the same granular way as a permissions boundary. Option C (incorrect) are elements in IAM policies that specify conditions for when a policy grants or denies access, but they don''t define a maximum permission set for an identity. Option D (incorrect) defines who can assume an IAM role, not the maximum permissions the assumed role can exercise.', 41, 'm_41_1', 21, NULL, NULL);

