INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_36_all_1775007670439', 'A financial services company needs to audit all API calls made to their AWS accounts for compliance and security forensics. They require a solution that allows long-term retention, immutable storage, and the ability to run complex SQL-based queries across years of event data, with the LEAST operational overhead.', '["Utilize AWS CloudTrail Lake to ingest and query CloudTrail events directly.","Configure AWS CloudTrail to deliver logs to Amazon S3, then use Amazon Athena for querying.","Stream AWS CloudTrail logs to Amazon Kinesis Data Firehose, then to Amazon OpenSearch Service for analysis.","Set up AWS CloudTrail to send logs to Amazon CloudWatch Logs, then export to Amazon S3 for archival."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) utilizes AWS CloudTrail Lake, which is specifically designed for immutable storage of CloudTrail events and allows running complex SQL-based queries across years of data with minimal operational overhead, as it is a fully managed service. Option B (incorrect) involves Amazon S3 for storage and Amazon Athena for querying, which is a valid approach but requires managing S3 lifecycle policies and setting up Athena tables, increasing operational overhead compared to CloudTrail Lake''s integrated solution. Option C (incorrect) streams logs to Amazon OpenSearch Service, which is excellent for real-time analytics and visualization but introduces the operational burden of managing an OpenSearch cluster and is not primarily designed for cost-effective, long-term archival and SQL-based querying of audit logs. Option D (incorrect) sends logs to Amazon CloudWatch Logs, which has retention limits and then requires an export to S3, adding complexity and operational steps for long-term archival and querying compared to CloudTrail Lake.', 39, 'm_39_2', 1, NULL, NULL),
  ('mock_36_all_1775007670439', 'A DevOps team manages a critical microservices application experiencing intermittent performance issues. They need to identify latency bottlenecks across multiple services, including AWS Lambda functions and Amazon API Gateway, and visualize service dependencies to pinpoint the root cause quickly. The solution must offer detailed trace analysis with MINIMAL configuration effort.', '["Implement custom Amazon CloudWatch metrics for each service and build dashboards.","Enable AWS X-Ray for distributed tracing across all microservices and visualize service maps.","Collect all application logs in Amazon CloudWatch Logs and use CloudWatch Logs Insights for querying.","Deploy a custom logging agent to send detailed performance data to Amazon OpenSearch Service."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) enables AWS X-Ray, which automatically collects data about requests that your application serves and provides a service map, trace details, and latency information across distributed services, including AWS Lambda and Amazon API Gateway, with minimal configuration. This directly addresses the need for visualizing service dependencies and identifying latency bottlenecks. Option A (incorrect) would require significant manual effort to define, implement, and aggregate custom metrics across all services, which does not meet the ''minimal configuration effort'' constraint. Option C (incorrect) uses CloudWatch Logs Insights for querying logs, which can help identify issues but does not provide a visual service map or end-to-end trace analysis across multiple services like X-Ray. Option D (incorrect) involves deploying and managing a custom logging agent and an Amazon OpenSearch Service cluster, which significantly increases operational overhead and configuration effort.', 39, 'm_39_2', 2, NULL, NULL),
  ('mock_36_all_1775007670439', 'A large e-commerce platform wants to proactively detect unusual behavior in their application logs, such as sudden spikes in error rates or a drop in successful transactions, without setting static thresholds that require constant adjustment. They need a solution that automatically learns normal patterns and alerts on significant deviations with HIGH accuracy.', '["Configure Amazon EventBridge rules to trigger AWS Lambda functions for custom anomaly detection.","Use Amazon CloudWatch Logs Insights to regularly query for high error rates and manually adjust alarms.","Implement Amazon CloudWatch anomaly detection on relevant metrics to automatically establish baselines and alert on deviations.","Set up static Amazon CloudWatch alarms on error rate metrics with fixed thresholds and review them periodically."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) leverages Amazon CloudWatch anomaly detection, which uses machine learning to analyze past metric data, establish dynamic baselines, and create alarms that trigger when the metric deviates significantly from the expected pattern. This directly addresses the need for automatic learning and high-accuracy detection without constant manual threshold adjustments (anti-pattern ap-4.2-001). Option A (incorrect) would require significant development and operational overhead to build and maintain custom anomaly detection logic using AWS Lambda and EventBridge. Option B (incorrect) involves manual querying and adjustment, which is reactive and high-effort, failing the ''automatically learns'' and ''high accuracy'' requirements. Option D (incorrect) relies on static thresholds, which are prone to false positives or negatives as application behavior changes, directly embodying the anti-pattern of not using anomaly detection for unknown-unknown failures.', 39, 'm_39_2', 3, NULL, NULL),
  ('mock_36_all_1775007670439', 'A security operations center (SOC) needs to integrate AWS CloudTrail logs and Amazon VPC Flow Logs into their existing Security Information and Event Management (SIEM) system for centralized security analysis and incident response. The solution must ensure real-time delivery and reliable data transfer to the SIEM, which is hosted on-premises.', '["Configure Amazon CloudWatch Logs subscription filters to stream logs to an AWS Lambda function, then to the SIEM.","Set up Amazon S3 event notifications to trigger an AWS Lambda function to push logs to the SIEM.","Use Amazon EventBridge to capture CloudTrail and VPC Flow Log events and forward them to the SIEM.","Stream logs from Amazon CloudWatch Logs or Amazon S3 to Amazon Kinesis Data Firehose, configured with a custom HTTP endpoint for the on-premises SIEM."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) uses Amazon Kinesis Data Firehose, which is a fully managed service for delivering real-time streaming data to destinations like Amazon S3, Amazon Redshift, Amazon OpenSearch Service, and generic HTTP endpoints. It provides reliable, scalable, and near real-time delivery, making it ideal for integrating with an on-premises SIEM via a custom HTTP endpoint. Option A (incorrect) involves an AWS Lambda function, which might introduce latency, scaling challenges, and requires custom code for reliable delivery and error handling, increasing operational overhead. Option B (incorrect) relies on S3 event notifications, which are not designed for real-time streaming of logs as they arrive, and would require custom Lambda code to push to the SIEM. Option C (incorrect) uses Amazon EventBridge, which is excellent for event-driven automation within AWS but is not designed for high-volume, real-time log streaming to external systems like an on-premises SIEM.', 39, 'm_39_2', 4, NULL, NULL),
  ('mock_36_all_1775007670439', 'A development team has deployed a new serverless application using AWS Lambda and Amazon DynamoDB. They need to quickly troubleshoot issues by analyzing application logs for specific error messages and performance metrics across multiple Lambda invocations. The solution must allow interactive, ad-hoc querying of log data with a SQL-like syntax.', '["Utilize Amazon CloudWatch Logs Insights to perform interactive queries on log groups.","Export logs from Amazon CloudWatch Logs to Amazon S3 and query using Amazon Athena.","Stream logs to Amazon OpenSearch Service and use Kibana for visualization and querying.","Use AWS CloudTrail Lake to query API invocation logs for performance issues."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon CloudWatch Logs Insights, which provides an interactive, SQL-like query language to search and analyze log data in Amazon CloudWatch Logs. This is perfectly suited for quickly troubleshooting issues across multiple Lambda invocations by filtering for specific error messages and performance metrics. Option B (incorrect) involves exporting logs to Amazon S3 and then using Amazon Athena, which adds extra steps, latency, and operational overhead for ad-hoc troubleshooting compared to direct querying in CloudWatch Logs Insights. Option C (incorrect) requires setting up and managing an Amazon OpenSearch Service cluster, which is a more complex and higher-overhead solution for interactive log querying, especially for a serverless application where simplicity is often preferred. Option D (incorrect) uses AWS CloudTrail Lake, which is designed for auditing API calls, not for analyzing application-specific logs from AWS Lambda functions.', 39, 'm_39_2', 5, NULL, NULL),
  ('mock_36_all_1775007670439', 'A DevOps engineer needs to create a consolidated view of critical operational metrics and logs from several AWS accounts to monitor the overall health of their production environment. They require a solution that aggregates data into a single dashboard and allows cross-account log search without complex manual setup.', '["Manually configure Amazon CloudWatch dashboards and log group permissions in each account.","Implement Amazon CloudWatch cross-account observability to centralize monitoring and log access.","Stream all logs from individual accounts to a central Amazon S3 bucket and use Amazon Athena for querying.","Set up Amazon Kinesis Data Firehose in each account to stream logs to a central Amazon OpenSearch Service domain."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) leverages Amazon CloudWatch cross-account observability, which is designed to provide a unified view of metrics, logs, and traces across multiple AWS accounts. It allows engineers to search logs and view metrics from linked accounts in a single monitoring account, significantly reducing complex manual setup for consolidated monitoring. Option A (incorrect) describes a manual, high-overhead approach that does not scale well and makes cross-account analysis cumbersome. Option C (incorrect) centralizes logs in S3, but querying with Athena requires setting up and managing tables, and it doesn''t provide a consolidated dashboard view or real-time log search capabilities inherent to CloudWatch. Option D (incorrect) involves setting up Kinesis Data Firehose and Amazon OpenSearch Service, which is a powerful centralized logging solution but typically involves more setup and management overhead than CloudWatch cross-account observability for simply consolidating monitoring and log access.', 39, 'm_39_2', 6, NULL, NULL),
  ('mock_36_all_1775007670439', 'An application experiences occasional spikes in API latency that are difficult to pinpoint using traditional metrics. The DevOps team wants to identify which specific API endpoints or user agents are contributing the most to these latency issues. They need a tool that can quickly analyze high-cardinality data to find top talkers or unique patterns.', '["Use Amazon CloudWatch Logs Insights to run custom queries on access logs.","Configure AWS X-Ray to trace requests and analyze service maps for latency.","Implement Amazon CloudWatch Contributor Insights to identify top N contributors to specific metrics.","Stream all access logs to Amazon OpenSearch Service and build custom dashboards."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) uses Amazon CloudWatch Contributor Insights, which is specifically designed to analyze high-cardinality data in logs and identify the top N contributors (e.g., specific API endpoints, user agents, IP addresses) to metric anomalies or patterns, such as latency spikes or error rates. This directly addresses the requirement to quickly find top talkers or unique patterns. Option A (incorrect) uses CloudWatch Logs Insights, which can query logs but requires writing complex queries to extract and aggregate top contributors, which is less efficient and immediate than Contributor Insights. Option B (incorrect) uses AWS X-Ray, which is excellent for end-to-end tracing and visualizing service dependencies, but its primary focus is not on quickly identifying top N contributors from high-cardinality log data in a summary view. Option D (incorrect) involves setting up and managing an Amazon OpenSearch Service cluster, which is a more complex solution for this specific use case and requires more operational overhead.', 39, 'm_39_2', 7, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_39_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_36_all_1775007670439', 'A company operates a critical application on Amazon EC2 instances. They need to automatically remediate instances that fail specific health checks, such as high CPU utilization or low disk space, by restarting them without manual intervention. The solution must be event-driven and scalable.', '["Use an Amazon CloudWatch alarm to trigger an Amazon SNS notification to the operations team.","Configure AWS Systems Manager Automation documents to run on a schedule to check instance health.","Set up an Amazon CloudWatch alarm to trigger an AWS Lambda function for manual review and restart.","Create an Amazon CloudWatch alarm that triggers an Amazon EventBridge rule, which then invokes an AWS Systems Manager Automation document to restart the instance."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) describes an event-driven, scalable, and automated remediation workflow. An Amazon CloudWatch alarm detects the health issue (e.g., high CPU), triggers an Amazon EventBridge rule, which then invokes an AWS Systems Manager Automation document to perform the restart. This provides a fully automated, hands-off solution. Option A (incorrect) only sends a notification, requiring manual intervention, which fails the ''without manual intervention'' requirement. Option B (incorrect) uses scheduled automation, which is not event-driven and might not react immediately to issues. Option C (incorrect) still implies manual review within the Lambda function or requires complex custom logic for automated restart, which is less robust and more complex than leveraging AWS Systems Manager Automation through EventBridge.', 39, 'm_39_3', 8, NULL, NULL),
  ('mock_36_all_1775007670439', 'A DevOps team wants to monitor custom application metrics, such as the number of active user sessions or specific business transaction counts, from their Amazon EC2 instances. They need to collect these metrics, visualize them on dashboards, and set alarms if they exceed predefined thresholds. The solution must be flexible for various application types.', '["Install the Amazon CloudWatch agent on EC2 instances to collect custom metrics and send them to Amazon CloudWatch for dashboards and alarms.","Develop custom scripts to push metrics to Amazon S3, then use Amazon Athena to query and visualize.","Use AWS X-Ray to collect application performance data and create custom dashboards.","Stream application logs to Amazon Kinesis Data Firehose, then to Amazon OpenSearch Service for metric extraction."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) involves installing the Amazon CloudWatch agent on Amazon EC2 instances. This agent is designed to collect both system-level and custom application metrics, which can then be sent to Amazon CloudWatch. Once in CloudWatch, these metrics can be easily visualized on custom dashboards and used to configure alarms, meeting all the specified requirements with flexibility for various application types. Option B (incorrect) would require significant custom development for scripts, S3 management, and Athena setup, increasing operational overhead and complexity compared to the managed CloudWatch agent. Option C (incorrect) uses AWS X-Ray, which is primarily for distributed tracing and service maps, not for collecting arbitrary custom business metrics. While it provides performance data, it''s not the best tool for general custom metric collection. Option D (incorrect) involves a more complex architecture with Kinesis Data Firehose and Amazon OpenSearch Service, which is suitable for log analytics but overkill and less direct for simply collecting and monitoring custom metrics.', 39, 'm_39_3', 9, NULL, NULL),
  ('mock_36_all_1775007670439', 'A global application relies on multiple microservices deployed across different AWS accounts. When an error occurs in one service, it often cascades, making root cause analysis difficult. The team needs a solution to trace requests end-to-end across these distributed services and accounts to understand the full path and identify failure points.', '["Aggregate all application logs into a central Amazon CloudWatch Logs account and use CloudWatch Logs Insights.","Implement AWS X-Ray across all microservices and accounts to enable distributed tracing and service maps.","Set up Amazon CloudWatch cross-account observability to view metrics and logs from a central account.","Deploy custom agents on each microservice to send performance data to Amazon OpenSearch Service for analysis."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is AWS X-Ray, which provides end-to-end distributed tracing across microservices, including those deployed in different AWS accounts. It generates a service map that visualizes service dependencies and identifies where errors and latency occur, making it ideal for root cause analysis in complex, distributed environments. Option A (incorrect) uses CloudWatch Logs Insights, which can query logs but does not provide the visual service map or end-to-end trace context needed to understand request flow across multiple services and accounts. Option C (incorrect) uses CloudWatch cross-account observability, which centralizes metrics and logs but does not offer the detailed, request-level tracing and service map visualization provided by X-Ray. Option D (incorrect) involves deploying and managing custom agents and an Amazon OpenSearch Service cluster, which is a higher operational overhead solution compared to the managed X-Ray service for distributed tracing.', 39, 'm_39_3', 10, NULL, NULL),
  ('mock_36_all_1775007670439', 'A development team needs to be notified immediately if any critical AWS resource (e.g., an Amazon EC2 instance or an Amazon RDS database) changes its configuration in an unauthorized way, potentially indicating a security breach or misconfiguration. They require an automated response to these changes.', '["Periodically review AWS CloudTrail logs for configuration changes and manually send notifications.","Set up Amazon CloudWatch alarms on resource utilization metrics to detect unusual activity.","Configure AWS Config rules to monitor resource compliance and use Amazon EventBridge to trigger automated remediation actions.","Use Amazon CloudWatch Logs Insights to query configuration change events and send email alerts."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) involves configuring AWS Config rules to continuously monitor AWS resource configurations for compliance with desired settings. When a non-compliant change is detected, AWS Config can send an event to Amazon EventBridge, which can then trigger automated remediation actions (e.g., an AWS Lambda function to revert the change or send an Amazon SNS notification). This provides immediate notification and automated response to unauthorized configuration changes. Option A (incorrect) requires manual review, which is not immediate or automated. Option B (incorrect) focuses on resource utilization, not configuration changes, and wouldn''t directly detect unauthorized modifications. Option D (incorrect) uses CloudWatch Logs Insights for querying, which is a reactive approach and does not provide immediate, automated responses to configuration changes.', 39, 'm_39_3', 11, NULL, NULL),
  ('mock_36_all_1775007670439', 'A company wants to detect and respond to unusual patterns in their application''s behavior, such as a sudden, unexpected increase in network traffic or a significant deviation from the typical request rate, without having to manually define static thresholds. The solution should use machine learning to adapt to changing baselines.', '["Utilize Amazon CloudWatch anomaly detection to automatically learn normal patterns and alert on deviations.","Implement Amazon CloudWatch Logs Insights queries to identify spikes in log data and create custom alarms.","Set up static Amazon CloudWatch alarms with fixed thresholds that are adjusted manually over time.","Stream all application metrics to Amazon OpenSearch Service and use its machine learning features for anomaly detection."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) uses Amazon CloudWatch anomaly detection, which is specifically designed to apply machine learning algorithms to historical metric data to create a dynamically adjusting baseline of expected behavior. It then alerts when current metric values fall outside this baseline, effectively detecting unusual patterns without static thresholds and adapting to changing baselines (anti-pattern ap-4.2-001). Option B (incorrect) relies on manual query creation and custom alarms, which is not automated or adaptive. Option C (incorrect) involves static thresholds that require constant manual adjustment, which is precisely what the company wants to avoid and is an anti-pattern. Option D (incorrect) involves setting up and managing an Amazon OpenSearch Service cluster and configuring its machine learning features, which is a more complex and higher operational overhead solution compared to the fully managed CloudWatch anomaly detection.', 39, 'm_39_3', 12, NULL, NULL),
  ('mock_36_all_1775007670439', 'A DevOps team needs to centralize all application and system logs from hundreds of Amazon EC2 instances and AWS Lambda functions into a single platform for real-time analysis and long-term archival. The solution must be highly scalable, managed, and support streaming to a dedicated log analytics service.', '["Configure each Amazon EC2 instance to send logs directly to Amazon CloudWatch Logs and use subscription filters for Lambda.","Use Amazon Kinesis Data Firehose to ingest logs from various sources and deliver them to Amazon OpenSearch Service and Amazon S3.","Manually copy log files from Amazon EC2 instances to a central Amazon S3 bucket for archival.","Set up an AWS Lambda function to poll logs from Amazon EC2 instances and push them to a central log server."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes a robust, scalable, and managed centralized logging architecture. Amazon Kinesis Data Firehose can ingest logs from various sources (e.g., CloudWatch Logs, custom agents on EC2) and reliably deliver them to Amazon OpenSearch Service for real-time analysis and Amazon S3 for long-term archival. This meets the requirements for scalability, managed service, and streaming to a dedicated log analytics service. Option A (incorrect) sends logs directly to CloudWatch Logs, which can then be streamed, but Kinesis Data Firehose provides a more direct and managed path for delivery to OpenSearch and S3, especially for high volumes. This also relates to anti-pattern ap-4.1-001 if logs are not routed centrally. Option C (incorrect) is a manual and inefficient approach that does not support real-time analysis or scalability. Option D (incorrect) involves custom development and managing a Lambda function for polling, which is less efficient and scalable than using a dedicated streaming service like Kinesis Data Firehose.', 39, 'm_39_3', 13, NULL, NULL),
  ('mock_36_all_1775007670439', 'A critical production system generates various operational events, such as AWS Auto Scaling lifecycle hooks, Amazon EC2 instance state changes, and custom application events. The DevOps team needs to trigger different automated actions, like sending notifications, invoking AWS Lambda functions, or starting AWS Systems Manager Automation documents, based on specific event patterns.', '["Use Amazon SNS topics to send notifications for all events, then manually trigger actions.","Configure Amazon CloudWatch alarms for specific metrics and manually link them to actions.","Implement Amazon EventBridge rules to match specific event patterns and trigger targeted actions.","Write custom scripts on Amazon EC2 instances to monitor logs and trigger actions locally."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) utilizes Amazon EventBridge, which is a serverless event bus that makes it easy to connect applications together using data from your own applications, integrated SaaS applications, and AWS services. It allows defining rules with specific event patterns to filter and route events to various targets, such as Amazon SNS, AWS Lambda functions, or AWS Systems Manager Automation documents, enabling highly flexible and automated responses. Option A (incorrect) uses Amazon SNS for notifications, but it doesn''t provide the event pattern matching and routing capabilities to trigger different automated actions based on event content. Option B (incorrect) uses CloudWatch alarms, which are metric-based and less suitable for handling diverse operational events with specific patterns. Option D (incorrect) involves custom scripting on EC2 instances, which is not scalable, increases operational overhead, and is not a managed, event-driven solution.', 39, 'm_39_3', 14, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_39_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_36_all_1775007670439', 'A large enterprise has multiple AWS accounts and needs to centralize all application and infrastructure logs for compliance and operational visibility. They want to aggregate logs from all accounts into a single Amazon OpenSearch Service domain in a dedicated logging account. The solution must be scalable and minimize data loss during ingestion.', '["Configure Amazon CloudWatch Logs subscription filters in each source account to stream logs directly to the central Amazon OpenSearch Service domain.","Manually configure AWS CloudTrail and Amazon VPC Flow Logs to deliver logs to a central Amazon S3 bucket, then use an AWS Lambda function to push to OpenSearch.","Set up a custom log forwarding agent on each Amazon EC2 instance to send logs directly to the central Amazon OpenSearch Service domain.","Use Amazon Kinesis Data Firehose in each source account to ingest logs and deliver them to a central Amazon OpenSearch Service domain in the logging account."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) uses Amazon Kinesis Data Firehose in each source account to ingest logs. Firehose is a fully managed service that reliably streams data to destinations like Amazon OpenSearch Service, handling scaling and minimizing data loss during ingestion. This provides a robust and scalable centralized logging architecture across multiple accounts. Option A (incorrect) involves CloudWatch Logs subscription filters, which can stream to OpenSearch but might require more complex cross-account permissions and management, and Firehose offers more robust buffering and delivery guarantees. Option B (incorrect) is a multi-step process that relies on S3 and a custom Lambda function, increasing operational overhead and potential for data loss or latency compared to Firehose. Option C (incorrect) involves deploying and managing custom agents on every EC2 instance, which significantly increases operational overhead and is an anti-pattern (ap-4.1-001) for centralized log routing, as it bypasses a managed aggregation layer.', 39, 'm_39_1', 15, NULL, NULL),
  ('mock_36_all_1775007670439', 'A DevOps team needs to collect detailed system-level metrics (e.g., memory utilization, disk I/O, process lists) and application logs from their Amazon EC2 instances running various operating systems. They require a single, unified agent that can send this data to Amazon CloudWatch for monitoring and analysis.', '["Install and configure the Amazon CloudWatch agent on all Amazon EC2 instances.","Use AWS Systems Manager Agent to collect metrics and logs and send them to Amazon CloudWatch.","Develop custom scripts to push metrics and logs to Amazon Kinesis Data Firehose.","Manually configure rsyslog or syslog-ng to forward logs to Amazon CloudWatch Logs."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is to install and configure the Amazon CloudWatch agent. This unified agent is specifically designed to collect both system-level metrics (including memory, disk I/O, process lists) and application logs from Amazon EC2 instances (and on-premises servers) running various operating systems, and then send them to Amazon CloudWatch for monitoring, dashboards, and alarms. Option B (incorrect) uses AWS Systems Manager Agent (SSM Agent), which is primarily for managing instances (e.g., running commands, patching) and does not natively collect detailed custom metrics and application logs for CloudWatch in the same way the CloudWatch agent does. Option C (incorrect) would require significant custom development and maintenance for scripts and Kinesis Data Firehose integration, increasing operational overhead. Option D (incorrect) involves manual configuration of traditional logging daemons, which is less integrated, scalable, and manageable than the CloudWatch agent for sending data to CloudWatch.', 39, 'm_39_1', 16, NULL, NULL),
  ('mock_36_all_1775007670439', 'A DevOps team has a microservices architecture and needs to visualize the flow of requests between services, identify dependencies, and pinpoint performance bottlenecks across different components, including Amazon EC2, AWS Lambda, and Amazon DynamoDB. They need a service map and detailed trace data.', '["Collect all logs in Amazon CloudWatch Logs and use CloudWatch Logs Insights for analysis.","Implement custom Amazon CloudWatch metrics for each service and create dashboards.","Utilize AWS X-Ray to trace requests, generate service maps, and analyze segment data.","Stream all application data to Amazon Kinesis Data Firehose and then to Amazon OpenSearch Service for visualization."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) utilizes AWS X-Ray, which is specifically designed for distributed tracing. It collects data about requests that your application serves, providing a visual service map that shows the relationships between services, and detailed trace data to identify performance bottlenecks and errors across components like Amazon EC2, AWS Lambda, and Amazon DynamoDB. Option A (incorrect) uses CloudWatch Logs Insights, which is good for querying log data but does not provide the visual service map or end-to-end trace context that X-Ray offers. Option B (incorrect) involves custom metrics and dashboards, which can show overall health but lack the granular, request-level tracing and dependency mapping needed for deep bottleneck analysis. Option D (incorrect) describes a log aggregation pipeline to Amazon OpenSearch Service, which is suitable for log analytics and visualization but not for distributed tracing and service map generation in the same way X-Ray is.', 39, 'm_39_1', 17, NULL, NULL),
  ('mock_36_all_1775007670439', 'A security team requires a centralized log aggregation solution for all AWS service logs (e.g., CloudTrail, VPC Flow Logs, S3 access logs) from multiple accounts. The aggregated logs need to be indexed and searchable for security investigations and compliance reporting, with a strong emphasis on real-time search and visualization capabilities.', '["Store all logs in a central Amazon S3 bucket and use Amazon Athena for querying.","Use Amazon CloudWatch Logs to aggregate logs from all accounts and use CloudWatch Logs Insights for searching.","Stream logs from each account to Amazon Kinesis Data Firehose, which delivers them to a central Amazon OpenSearch Service domain.","Configure AWS CloudTrail Lake to ingest all service logs for centralized querying."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes a robust centralized logging solution for real-time search and visualization. Amazon Kinesis Data Firehose is a fully managed service for delivering real-time streaming data, which can ingest logs from various AWS services and accounts. It reliably delivers this data to a central Amazon OpenSearch Service domain, which provides powerful indexing, real-time search, and visualization capabilities (like Kibana) essential for security investigations and compliance reporting. Option A (incorrect) uses Amazon S3 and Amazon Athena, which is cost-effective for long-term storage and ad-hoc querying but lacks the real-time indexing, search, and visualization capabilities of OpenSearch Service. Option B (incorrect) uses Amazon CloudWatch Logs, which can aggregate logs but its search and visualization capabilities are not as powerful or real-time as a dedicated OpenSearch Service cluster for large-scale, cross-service log analysis. Option D (incorrect) uses AWS CloudTrail Lake, which is specifically for CloudTrail events (API activity) and not a general-purpose solution for all AWS service logs like VPC Flow Logs or S3 access logs.', 39, 'm_39_1', 18, NULL, NULL),
  ('mock_36_all_1775007670439', 'A company is migrating an application with custom metrics that are critical for business operations. They need to ensure these metrics are collected from on-premises servers and Amazon EC2 instances, aggregated, and available for real-time monitoring and alarming in AWS. The solution should support both push and pull mechanisms for metrics.', '["Deploy the Amazon CloudWatch agent on both on-premises servers and Amazon EC2 instances to collect and send custom metrics to Amazon CloudWatch.","Develop custom scripts to periodically push metrics from on-premises servers to an Amazon S3 bucket, and use Amazon Athena for visualization.","Use AWS Systems Manager to collect metrics from Amazon EC2 instances and Amazon EventBridge to trigger alerts.","Stream all metric data to Amazon Kinesis Data Firehose and then to Amazon OpenSearch Service for monitoring."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) involves deploying the Amazon CloudWatch agent, which is designed to collect custom metrics from both on-premises servers and Amazon EC2 instances. It supports both push (for custom metrics) and pull (for standard system metrics) mechanisms and sends data directly to Amazon CloudWatch, where it can be used for real-time monitoring, dashboards, and alarms. This is the most direct and managed solution for this requirement. Option B (incorrect) uses Amazon S3 and Amazon Athena, which is suitable for historical analysis but not for real-time monitoring and alarming. It also requires significant custom development. Option C (incorrect) uses AWS Systems Manager, which is primarily for instance management, and Amazon EventBridge for alerts, but neither is designed for the direct collection and aggregation of diverse custom metrics from both on-premises and EC2 for CloudWatch. Option D (incorrect) involves Kinesis Data Firehose and Amazon OpenSearch Service, which is a powerful log/data analytics platform but is an overly complex and higher-cost solution for simply collecting and monitoring custom metrics in real-time.', 39, 'm_39_1', 19, NULL, NULL),
  ('mock_36_all_1775007670439', 'A DevOps engineer needs to troubleshoot an issue where a specific microservice is intermittently failing. They suspect the issue might be related to a high volume of requests from a particular source IP or user agent. They need to quickly identify the top N contributors to the service''s request volume or error rate in real-time.', '["Use Amazon CloudWatch Logs Insights to run ad-hoc queries on access logs to find top IPs.","Configure AWS X-Ray to trace requests and analyze individual traces for problematic IPs.","Stream all access logs to Amazon Kinesis Data Firehose and then to Amazon S3 for batch analysis.","Implement Amazon CloudWatch Contributor Insights to identify top N contributors based on log fields like source IP or user agent."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) uses Amazon CloudWatch Contributor Insights, which is specifically designed to analyze high-cardinality data in logs and identify the top N contributors (e.g., source IP addresses, user agents) to specific metrics or log patterns, such as request volume or error rates, in near real-time. This directly addresses the need to quickly identify top contributors. Option A (incorrect) uses CloudWatch Logs Insights, which can query logs but requires writing and running complex queries to extract and aggregate top contributors, which is less efficient and immediate than Contributor Insights for this specific task. Option B (incorrect) uses AWS X-Ray, which provides detailed traces for individual requests but is not optimized for quickly summarizing top contributors across a large volume of requests. Option C (incorrect) involves streaming logs to Amazon S3 for batch analysis, which is not suitable for real-time identification of top contributors.', 39, 'm_39_1', 20, NULL, NULL);

