-- Module: m_40_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_36_all_1775007670439', 'A company operates several microservices across multiple AWS accounts. They need a centralized mechanism to route events from various AWS services (e.g., Amazon S3, AWS Lambda, Amazon EC2) to different targets in other accounts, such as monitoring systems or remediation Lambda functions. The solution must support content-based filtering and schema validation with the LEAST custom code. Which AWS service should be used?', '["Amazon EventBridge","Amazon SQS","Amazon SNS","AWS Lambda"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon EventBridge. It acts as a serverless event bus that makes it easy to connect applications together using data from your own applications, integrated SaaS applications, and AWS services. EventBridge supports content-based filtering, schema validation with its Schema Registry, and cross-account event routing, making it ideal for centralized event management across multiple accounts with minimal custom code. Option B (incorrect) Amazon SQS is a message queuing service, primarily used for decoupling microservices and buffering messages. While it can receive events, it doesn''t provide the advanced routing, filtering, or cross-account capabilities of EventBridge without significant custom logic. Option C (incorrect) Amazon SNS is a pub/sub messaging service for fan-out notifications. It can distribute messages to multiple subscribers but lacks the sophisticated content-based filtering, schema validation, and direct cross-account routing capabilities of EventBridge. Option D (incorrect) AWS Lambda is a compute service for running code. While Lambda can process events, building custom event routing logic within Lambda functions for all sources and targets would be an anti-pattern (ap-5.1-001) as it adds undifferentiated heavy lifting and complexity that EventBridge handles natively.', 40, 'm_40_1', 8, NULL, NULL),
  ('mock_36_all_1775007670439', 'A security team needs to automatically respond to Amazon GuardDuty findings, specifically when a high-severity threat is detected, such as unauthorized access to an Amazon S3 bucket. The response should involve immediately blocking the suspicious IP address, notifying the security team, and creating an operational issue for tracking. Which architecture provides the MOST automated response?', '["Configure an Amazon EventBridge rule to capture Amazon GuardDuty findings, filter for high-severity S3 threats, and trigger an AWS Lambda function to update AWS WAF IP sets. Simultaneously, publish a message to an Amazon SNS topic for notifications and create an OpsItem in AWS Systems Manager OpsCenter.","Manually review Amazon GuardDuty findings daily, and for high-severity threats, manually update AWS WAF rules and send an email to the security team.","Set up an Amazon SNS topic to receive all Amazon GuardDuty findings, and have a security analyst subscribe to the topic to manually review and respond to alerts.","Create a custom AWS Lambda function that periodically polls Amazon GuardDuty for new findings, and if a high-severity S3 threat is found, the Lambda function directly blocks the IP and sends a notification."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most automated and integrated response. Amazon GuardDuty findings are published to Amazon EventBridge. An EventBridge rule can filter these findings based on severity and resource type. This rule can then trigger an AWS Lambda function to perform automated remediation actions, such as updating AWS WAF IP sets to block suspicious IPs. Simultaneously, EventBridge can publish to an Amazon SNS topic for immediate notifications and create an OpsItem in AWS Systems Manager OpsCenter for centralized tracking and management of the security incident. Option B (incorrect) relies on manual review and response, which does not meet the ''MOST automated response'' requirement and is prone to delays. Option C (incorrect) uses Amazon SNS for notification but still requires manual review and response, failing the automation requirement. Option D (incorrect) involves a custom Lambda function polling GuardDuty, which is an anti-pattern (ap-5.1-001) for event processing as it adds undifferentiated heavy lifting and is less efficient than EventBridge''s native integration with GuardDuty.', 40, 'm_40_1', 9, NULL, NULL),
  ('mock_36_all_1775007670439', 'A media company processes high volumes of video upload events from Amazon S3. Multiple downstream services need to be notified of these new uploads for tasks like transcoding, metadata extraction, and archiving. The solution must ensure that all consumers receive the event, even if they are temporarily unavailable, and allow for fan-out to different types of consumers. Which architecture should a DevOps Engineer implement?', '["Configure an Amazon EventBridge rule to capture S3 PutObject events, and route them to an Amazon SNS topic. The SNS topic should then fan out messages to multiple Amazon SQS queues, one for each consumer service.","Develop a single AWS Lambda function that is triggered by S3 PutObject events. This Lambda function will then directly invoke each downstream service''s API.","Set up an Amazon SQS queue to receive S3 PutObject events, and have each consumer service poll this single queue, filtering messages based on their needs.","Create custom HTTP endpoints for each consumer service and configure S3 event notifications to send direct HTTP POST requests to each endpoint."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a robust and scalable fan-out pattern. Amazon EventBridge can capture S3 PutObject events with powerful filtering capabilities. Routing these events to an Amazon SNS topic allows for fan-out to multiple subscribers. By subscribing Amazon SQS queues to the SNS topic, each consumer service gets its own queue, ensuring message durability and independent processing, even if a consumer is temporarily unavailable. This decouples the producers from consumers effectively. Option B (incorrect) creates tight coupling between the S3 event and all downstream services. If one service fails, the Lambda function might fail or require complex error handling, and it doesn''t provide message durability for individual consumers. Option C (incorrect) uses a single SQS queue, which would require each consumer to poll the same queue and implement its own filtering logic, leading to potential contention, increased complexity, and less efficient message distribution compared to SNS fan-out. Option D (incorrect) involves custom HTTP endpoints and direct S3 notifications, which lacks the durability, retry mechanisms, and advanced routing capabilities provided by EventBridge, SNS, and SQS, and increases operational overhead for managing endpoints.', 40, 'm_40_1', 10, NULL, NULL),
  ('mock_36_all_1775007670439', 'A financial institution needs to be proactively informed about potential service degradations or scheduled maintenance events that could impact their AWS resources. They require an automated mechanism to receive these notifications and trigger specific internal workflows. Which service combination should be used to achieve this?', '["Integrate AWS Health with Amazon EventBridge to capture specific account-specific events, and configure EventBridge rules to trigger AWS Lambda functions for custom workflow execution or publish to Amazon SNS for notifications.","Periodically check the AWS Health Dashboard manually for new events and then trigger internal workflows based on human review.","Set up an Amazon SNS topic to receive all AWS CloudTrail events, and filter these events to identify service degradation notices.","Develop a custom application that uses the AWS SDK to poll the AWS Health API for new events every hour, and then process them."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the recommended and most automated approach. AWS Health publishes account-specific events (such as scheduled maintenance, service degradations, or resource state changes) to Amazon EventBridge. EventBridge rules can then be configured to filter for specific event types or impact levels and trigger various targets, including AWS Lambda functions for automated workflow execution or Amazon SNS topics for notifications to relevant teams. This provides a robust, event-driven, and automated response. Option B (incorrect) relies on manual checking, which is not proactive or automated and does not meet the requirement for an automated mechanism. Option C (incorrect) AWS CloudTrail logs API activity and resource changes, but it is not the primary source for AWS service health events; AWS Health is. Filtering CloudTrail for service degradation notices would be inefficient and unreliable. Option D (incorrect) involves building a custom polling application, which is an anti-pattern (ap-5.1-001) as it adds undifferentiated heavy lifting for custom event routing logic that EventBridge handles natively, increasing operational overhead.', 40, 'm_40_1', 11, NULL, NULL),
  ('mock_36_all_1775007670439', 'A security operations center (SOC) needs to centralize security findings from multiple AWS accounts into a single security account for analysis and automated remediation. They want to ensure that all Amazon GuardDuty findings from member accounts are routed to a dedicated event bus in the SOC account. Which EventBridge feature should be leveraged?', '["Cross-account event routing using Amazon EventBridge event buses.","Amazon SNS fan-out to multiple SQS queues in different accounts.","AWS Lambda functions in each member account to push findings to the SOC account.","AWS Config rules to aggregate GuardDuty findings across accounts."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the purpose-built feature for this scenario. Amazon EventBridge allows for cross-account event routing by configuring event buses in different accounts to send and receive events. Member accounts can send their GuardDuty findings to a central event bus in the SOC account, where rules can then be applied for analysis and remediation. This is a native, secure, and scalable solution. Option B (incorrect) Amazon SNS fan-out to SQS queues can distribute messages, but it''s not designed for the sophisticated event routing, filtering, and schema capabilities across accounts that EventBridge offers for a centralized event bus. It would require more custom configuration to achieve the same level of integration. Option C (incorrect) involves building custom AWS Lambda functions in each member account to push findings, which is an anti-pattern (ap-5.1-001) as it adds undifferentiated heavy lifting for custom event routing logic that EventBridge handles natively, increasing complexity and operational overhead. Option D (incorrect) AWS Config is for compliance monitoring and auto-remediation of resource configurations, not for aggregating real-time security findings from Amazon GuardDuty across accounts.', 40, 'm_40_1', 12, NULL, NULL),
  ('mock_36_all_1775007670439', 'A company requires real-time processing of configuration changes detected by AWS Config. For specific resource types, they need to trigger custom validation logic and potentially initiate remediation actions. The solution must be event-driven and minimize polling. Which combination of services should a DevOps Engineer use?', '["Configure AWS Config to send notifications to an Amazon EventBridge default event bus, and create an EventBridge rule to filter for specific Config events, triggering an AWS Lambda function for custom logic and remediation.","Develop a custom AWS Lambda function that periodically polls AWS Config for new configuration items and then applies custom validation logic.","Set up an Amazon SNS topic to receive all AWS Config notifications, and subscribe an email address for manual review and action.","Use AWS Systems Manager Automation documents to periodically check AWS Config compliance status and trigger remediation actions."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides an event-driven and efficient solution. AWS Config publishes configuration changes and compliance events to Amazon EventBridge''s default event bus. An EventBridge rule can be configured to filter these specific Config events (e.g., for a particular resource type or compliance status) and then trigger an AWS Lambda function. The Lambda function can contain the custom validation logic and initiate remediation actions, ensuring real-time processing without polling. Option B (incorrect) involves custom Lambda polling, which is an anti-pattern (ap-5.1-001) for event processing, as it is less efficient and introduces latency compared to EventBridge''s real-time event delivery. Option C (incorrect) relies on manual review via email, which does not meet the requirement for real-time, automated processing and remediation. Option D (incorrect) uses AWS Systems Manager Automation documents for periodic checks, which is not real-time and involves polling, failing to meet the event-driven requirement.', 40, 'm_40_1', 13, NULL, NULL),
  ('mock_36_all_1775007670439', 'A DevOps team needs to distribute critical alerts to multiple communication channels, including email, SMS, and a custom chat application, whenever a significant event occurs in their AWS environment. The solution must ensure high availability and allow for easy addition or removal of new communication endpoints. Which AWS service is best suited for this fan-out notification pattern?', '["Amazon SNS","Amazon EventBridge","Amazon SQS","AWS Lambda"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon SNS (Simple Notification Service). SNS is a highly available, durable, secure, fully managed pub/sub messaging service that enables you to decouple microservices, distributed systems, and serverless applications. It is ideal for fan-out scenarios where a single message needs to be delivered to multiple subscribers (e.g., email, SMS, HTTP/S endpoints for custom applications, Lambda functions). Option B (incorrect) Amazon EventBridge is an event bus service for routing events from various sources to targets. While it can trigger SNS topics, its primary role is event routing and filtering, not fan-out notification to diverse endpoints itself. Option C (incorrect) Amazon SQS (Simple Queue Service) is a message queuing service used for decoupling and buffering messages between distributed systems. It''s designed for point-to-point or multiple consumers pulling from a queue, not for pushing a single message to multiple diverse endpoints simultaneously. Option D (incorrect) AWS Lambda is a serverless compute service. While a Lambda function could be written to send messages to multiple endpoints, this would involve custom code and managing the fan-out logic, which is an anti-pattern (ap-5.1-001) as SNS provides this capability natively with less operational overhead.', 40, 'm_40_1', 14, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_40_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_36_all_1775007670439', 'A DevOps team needs a centralized system to aggregate operational issues from various monitoring sources (e.g., AWS Config, Amazon GuardDuty, custom application alerts) and provide a single pane of glass for investigation and resolution. The system should allow for manual or automated execution of runbooks to address these issues. Which AWS service is designed for this purpose?', '["AWS Systems Manager OpsCenter","AWS Systems Manager Incident Manager","Amazon EventBridge","Amazon SNS"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is AWS Systems Manager OpsCenter. It provides a centralized console where operational issues (OpsItems) are aggregated from various AWS services and custom sources. Engineers can view contextual information, execute AWS Systems Manager Automation runbooks to diagnose and remediate problems, and track the status of these issues. It''s ideal for a ''single pane of glass'' for operational issues. Option B (incorrect) AWS Systems Manager Incident Manager is designed for structured incident response, including escalation paths, contact management, and post-incident analysis for critical incidents, which is a more specialized use case than general operational issue aggregation and resolution. Option C (incorrect) Amazon EventBridge is an event bus service for routing events, not a centralized dashboard for managing operational issues. While it can be used to create OpsItems, it doesn''t provide the management interface itself. Option D (incorrect) Amazon SNS is a messaging service for notifications, not for aggregating, investigating, and resolving operational issues.', 40, 'm_40_3', 15, NULL, NULL),
  ('mock_36_all_1775007670439', 'A critical production application has experienced an outage. The DevOps team needs a structured way to manage the incident, including defining severity levels, assigning responders, tracking communication, and ensuring proper escalation. After resolution, a post-incident review process is required. Which AWS service should be used to facilitate this process?', '["AWS Systems Manager Incident Manager","AWS Systems Manager OpsCenter","Amazon EventBridge","AWS Lambda"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is AWS Systems Manager Incident Manager. It is specifically designed for structured incident response, offering capabilities to define incident types, severity levels, escalation plans, contact management, communication channels, and post-incident analysis. It provides a comprehensive framework for managing critical incidents from detection to resolution and review. Option B (incorrect) AWS Systems Manager OpsCenter is for centralizing operational issues (OpsItems) and executing runbooks for routine problems, but it lacks the full structured incident response, escalation management, and post-incident analysis features of Incident Manager. Option C (incorrect) Amazon EventBridge is an event bus service for routing events, which can be used to trigger an incident, but it does not provide the incident management framework itself. Option D (incorrect) AWS Lambda is a serverless compute service used for running code. While Lambda can be part of an automated response, it does not provide the overarching incident management framework required.', 40, 'm_40_3', 16, NULL, NULL),
  ('mock_36_all_1775007670439', 'An application is experiencing intermittent errors, and the DevOps team wants to automatically trigger a diagnostic runbook whenever a specific error pattern appears in the application logs. The solution needs to be event-driven and execute a predefined set of AWS Systems Manager Automation steps. Which service combination achieves this?', '["Configure Amazon EventBridge to capture specific CloudWatch Logs events (via a Log Group subscription filter) that match the error pattern, and then trigger an AWS Lambda function to execute an AWS Systems Manager Automation document.","Manually monitor application logs in CloudWatch Logs and, upon detecting the error pattern, manually execute the diagnostic runbook in AWS Systems Manager.","Develop a custom script on an Amazon EC2 instance that continuously tails application logs, and when the error pattern is found, uses the AWS CLI to start an AWS Systems Manager Automation document.","Set up an Amazon SNS topic to receive all application logs, and subscribe an email address to notify a human operator who will then decide whether to run the diagnostic."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides an automated, event-driven solution. CloudWatch Logs can be configured with subscription filters to send specific log events (matching an error pattern) to Amazon EventBridge (via a CloudWatch Logs destination which can be an EventBridge event bus). An EventBridge rule can then capture these events and trigger an AWS Lambda function. The Lambda function can then invoke an AWS Systems Manager Automation document to execute the predefined diagnostic steps. This minimizes custom routing logic and leverages native AWS integrations. Option B (incorrect) relies on manual monitoring and execution, which does not meet the automation requirement and embodies the anti-pattern of manually responding to every event. Option C (incorrect) involves custom scripting on an EC2 instance, which is an anti-pattern for undifferentiated heavy lifting, increases operational overhead, and is less resilient than native AWS event processing. Option D (incorrect) relies on human intervention for decision-making and execution, failing to meet the automation requirement.', 40, 'm_40_3', 17, NULL, NULL),
  ('mock_36_all_1775007670439', 'A company needs to proactively detect and be notified of potential resource health issues, such as an Amazon EC2 instance reaching a critical CPU threshold or an Amazon RDS database running out of storage. The notifications should be sent to a specific team via email and a chat application. Which service combination should be used?', '["Configure Amazon EventBridge to capture AWS Health events and CloudWatch Alarms, then use EventBridge rules to publish messages to an Amazon SNS topic, which has subscriptions for email and a custom HTTP endpoint for the chat application.","Manually monitor the AWS Health Dashboard and CloudWatch metrics for anomalies, and then send manual emails to the team.","Develop a custom AWS Lambda function that periodically polls CloudWatch metrics and AWS Health events, and sends notifications via a custom email client.","Set up AWS Systems Manager OpsCenter to collect all operational issues, and have the team regularly check OpsCenter for new alerts."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a robust and automated solution. Amazon EventBridge can capture events from various sources, including AWS Health (for service-level issues) and CloudWatch Alarms (for resource-specific metrics like CPU or storage). EventBridge rules can then filter these events and route them to an Amazon SNS topic. SNS can fan out notifications to multiple subscribers, including email and HTTP/S endpoints for integrating with custom chat applications, ensuring the team receives alerts via their preferred channels. Option B (incorrect) relies on manual monitoring and notification, which is not proactive or automated. Option C (incorrect) involves custom Lambda polling, which is an anti-pattern (ap-5.1-001) for event processing, adding undifferentiated heavy lifting and being less efficient than EventBridge''s native integrations. Option D (incorrect) AWS Systems Manager OpsCenter is for aggregating and managing operational issues, but it doesn''t directly handle the proactive detection and multi-channel notification aspect as efficiently as EventBridge and SNS combined.', 40, 'm_40_3', 18, NULL, NULL),
  ('mock_36_all_1775007670439', 'A DevOps team wants to automate the rollback of failed AWS CloudFormation stack deployments. When a stack fails to deploy, an event should trigger a process that initiates a rollback to the last known good state. The solution must be event-driven and require minimal custom code for routing. Which approach should be taken?', '["Configure an Amazon EventBridge rule to capture CloudFormation stack status change events (e.g., `UPDATE_ROLLBACK_FAILED`, `CREATE_FAILED`), and trigger an AWS Lambda function to initiate a `rollback` action using AWS Systems Manager Automation.","Manually monitor CloudFormation deployment statuses in the AWS Management Console and, upon failure, manually execute a rollback.","Develop a custom AWS Lambda function that periodically polls CloudFormation stack statuses and, if a failure is detected, triggers a rollback.","Set up an Amazon SNS topic to receive all CloudFormation events, and subscribe a team member to manually decide on and initiate rollbacks."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides an automated, event-driven solution with minimal custom routing logic. CloudFormation stack events are published to Amazon EventBridge. An EventBridge rule can be configured to filter for specific failure statuses. This rule can then trigger an AWS Lambda function, which can execute an AWS Systems Manager Automation document designed to perform the rollback. This leverages native AWS services for event capture, routing, and automated action. Option B (incorrect) relies on manual monitoring and intervention, which does not meet the automation requirement. Option C (incorrect) involves custom Lambda polling, which is an anti-pattern (ap-5.1-001) for event processing, adding undifferentiated heavy lifting and being less efficient than EventBridge''s real-time event delivery. Option D (incorrect) uses Amazon SNS for notification, but still requires manual decision-making and action, failing to meet the automation requirement.', 40, 'm_40_3', 19, NULL, NULL),
  ('mock_36_all_1775007670439', 'A security team needs to respond to Amazon GuardDuty findings by automatically isolating affected Amazon EC2 instances for forensic analysis and creating a detailed operational issue for the incident response team. The solution must ensure that the isolation process is standardized and tracked. Which combination of services should be implemented?', '["Configure an Amazon EventBridge rule to capture Amazon GuardDuty findings, trigger an AWS Lambda function to modify EC2 security groups for isolation, and create an OpsItem in AWS Systems Manager OpsCenter for tracking and further actions.","Manually review Amazon GuardDuty findings, then manually modify EC2 security groups and log the incident in a spreadsheet.","Set up an Amazon SNS topic to receive all GuardDuty findings, and have a security analyst manually isolate instances and create an incident in AWS Systems Manager Incident Manager.","Develop a custom script on an Amazon EC2 instance that periodically polls GuardDuty for findings, and if a critical finding is detected, executes AWS CLI commands to isolate the instance."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides an automated, integrated, and tracked solution. Amazon GuardDuty findings are published to Amazon EventBridge. An EventBridge rule can filter for specific findings and trigger an AWS Lambda function. This Lambda function can then programmatically modify EC2 security groups to isolate the affected instance. Concurrently, an OpsItem can be created in AWS Systems Manager OpsCenter, providing a centralized record for the incident response team to track, investigate, and perform further actions using predefined runbooks. Option B (incorrect) relies on manual review and action, which does not meet the automation requirement and is prone to errors and delays. Option C (incorrect) uses Amazon SNS for notification but still requires manual isolation, failing the automation requirement. While Incident Manager is good for structured response, OpsCenter is better for tracking individual operational issues and runbook execution for this specific task. Option D (incorrect) involves custom scripting and polling, which is an anti-pattern (ap-5.1-001) for event processing, adds undifferentiated heavy lifting, and lacks native integration with AWS incident tracking services.', 40, 'm_40_3', 20, NULL, NULL);

